<?php
declare(strict_types=1);

/* REST API v1. Apply database/v1_migration.sql before using these routes. */
require_once dirname(__DIR__) . '/config.php';

function api_ok(mixed $data, int $status = 200, ?array $meta = null): never {
    http_response_code($status); header('Content-Type: application/json; charset=utf-8');
    header('Access-Control-Allow-Origin: ' . tpk_cors_origin()); header('Vary: Origin');
    header('Access-Control-Allow-Headers: Content-Type, Authorization, X-TPK-User-Id');
    header('Access-Control-Allow-Methods: GET, POST, PATCH, DELETE, OPTIONS');
    $payload = ['success' => true, 'data' => $data]; if ($meta) $payload['meta'] = $meta;
    echo json_encode($payload, JSON_UNESCAPED_SLASHES); exit;
}
function api_error(string $code, string $message, int $status = 400): never {
    http_response_code($status); header('Content-Type: application/json; charset=utf-8');
    header('Access-Control-Allow-Origin: ' . tpk_cors_origin()); header('Vary: Origin');
    echo json_encode(['success' => false, 'error' => ['code' => $code, 'message' => $message]], JSON_UNESCAPED_SLASHES); exit;
}
function api_input(): array { $v = json_decode(file_get_contents('php://input') ?: '{}', true); if (!is_array($v)) api_error('INVALID_JSON', 'Request body must be valid JSON.'); return $v; }
function api_path(): string { return rtrim(parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH) ?: '/', '/'); }
function api_method(): string { return strtoupper($_SERVER['REQUEST_METHOD'] ?? 'GET'); }
function api_phone(?string $value): ?string { $v = preg_replace('/\D+/', '', (string)$value); if (!$v) return null; if (str_starts_with($v, '234') && strlen($v) === 13) $v = '0' . substr($v, 3); return strlen($v) === 11 && str_starts_with($v, '0') ? $v : null; }
function api_page(): array { $page=max(1,(int)($_GET['page']??1)); $limit=min(100,max(1,(int)($_GET['limit']??25))); return [$page,$limit,($page-1)*$limit]; }
function api_db(): PDO { return db(); }
/* New workspace tables are optional while older campuses are being upgraded.  Read
 * screens must still work with the core attendance schema during that transition. */
function api_table_exists(PDO $db, string $table): bool {
    static $cache=[]; if(array_key_exists($table,$cache))return $cache[$table];
    $s=$db->prepare('SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=? LIMIT 1');$s->execute([$table]);
    return $cache[$table]=(bool)$s->fetchColumn();
}
function api_column_exists(PDO $db, string $table, string $column): bool {
    static $cache=[];$key="$table.$column";if(array_key_exists($key,$cache))return $cache[$key];
    $s=$db->prepare('SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=? AND column_name=? LIMIT 1');$s->execute([$table,$column]);
    return $cache[$key]=(bool)$s->fetchColumn();
}
function api_actor(PDO $db, bool $super = false): array {
    $authorization = $_SERVER['HTTP_AUTHORIZATION'] ?? '';
    if (!preg_match('/^Bearer\\s+([a-f0-9]{64})$/i', $authorization, $match)) api_error('UNAUTHENTICATED','Sign in is required.',401);
    $s=$db->prepare("SELECT s.id,s.campus_id,s.name,s.email,s.is_active,s.access_level,s.team_status,s.account_status FROM staff_sessions ss JOIN staff_users s ON s.id=ss.staff_user_id WHERE ss.token_hash=? AND ss.revoked_at IS NULL AND ss.expires_at>NOW() LIMIT 1");
    $s->execute([hash('sha256', $match[1])]); $user=$s->fetch();
    if (!$user || !(bool)$user['is_active'] || $user['account_status'] !== 'VERIFIED' || $user['team_status'] === 'INACTIVE') api_error('UNAUTHENTICATED','Your account is not active.',401);
    if ($super && $user['access_level'] !== 'TPK_SUPER_ADMIN') api_error('FORBIDDEN','TPK Super Admin access is required.',403);
    return $user;
}
function api_is_followup_lead(array $actor): bool {
    return in_array((string)$actor['access_level'], ['TPK_SUPER_ADMIN','TPK_FOLLOW_UP_ADMIN'], true);
}
function api_audit(PDO $db, array $actor, string $action, string $entity, int $id, array $meta=[]): void {
    audit($db,(int)$actor['campus_id'],$action,$entity,$id,$meta);
}
function api_permitted_class_ids(PDO $db, array $actor): ?array {
    if ($actor['access_level'] === 'TPK_SUPER_ADMIN') return null;
    $ids=[];
    if(api_table_exists($db,'roster_assignments')){$s=$db->prepare("SELECT DISTINCT class_id FROM roster_assignments WHERE user_id=? AND class_id IS NOT NULL AND assignment_date >= DATE_SUB(CURDATE(), INTERVAL 7 DAY) AND assignment_date <= DATE_ADD(CURDATE(), INTERVAL 30 DAY) AND status NOT IN ('CANCELLED','REPLACED')"); $s->execute([$actor['id']]);foreach($s->fetchAll() as $row) $ids[]=(int)$row['class_id'];}
    if (!$ids && api_table_exists($db,'staff_class_assignments')) { $s=$db->prepare('SELECT class_id FROM staff_class_assignments WHERE staff_user_id=? AND is_active=1'); $s->execute([$actor['id']]); foreach($s->fetchAll() as $row) $ids[]=(int)$row['class_id']; }
    return array_values(array_unique($ids));
}
function api_child_select(): string { return 'c.id,c.family_id AS familyId,c.first_name AS firstName,c.last_name AS lastName,c.date_of_birth AS dateOfBirth,c.gender,c.school_grade AS schoolGrade,c.class_id AS classId,COALESCE(c.joined_at,DATE(f.created_at)) AS joinedAt,c.is_active AS active,c.class_assignment_required AS classAssignmentRequired,c.is_first_visit AS isFirstVisit,cl.name AS className'; }
function api_child_age(?string $birthDate): ?int { if (!$birthDate) return null; try { return (new DateTimeImmutable($birthDate))->diff(new DateTimeImmutable('today'))->y; } catch (Throwable) { return null; } }
function api_child_profile_fields(array $child): array {
    $missing=[];
    if(empty($child['dateOfBirth']))$missing[]='Date of Birth';
    if(empty($child['gender']))$missing[]='Gender';
    if(empty($child['classId']))$missing[]='Class';
    if(empty($child['guardianId']))$missing[]='Primary Guardian';
    if(empty($child['guardianPhone']))$missing[]='Guardian Phone Number';
    return $missing;
}
function api_children_summary(PDO $db): never {
    $actor=api_actor($db);$allowed=null;$where=['f.campus_id=?'];$params=[$actor['campus_id']];
    if($allowed!==null){if(!$allowed)api_ok(['registeredChildren'=>0,'active'=>0,'presentThisSunday'=>0,'male'=>0,'female'=>0,'currentSundayDate'=>null]);$where[]='c.class_id IN ('.implode(',',array_fill(0,count($allowed),'?')).')';$params=array_merge($params,$allowed);}
    $filter=' WHERE '.implode(' AND ',$where);
    $sql="SELECT COUNT(*) AS registeredChildren,SUM(c.is_active=1) AS active,SUM(c.gender='MALE') AS male,SUM(c.gender='FEMALE') AS female FROM children c JOIN families f ON f.id=c.family_id$filter";
    $s=$db->prepare($sql);$s->execute($params);$row=$s->fetch()?:[];$registered=(int)($row['registeredChildren']??0);$currentSunday=api_latest_completed_sunday($db,(int)$actor['campus_id']);$present=0;if($currentSunday){$presence=$db->prepare("SELECT COUNT(DISTINCT a.child_id) FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id JOIN children c ON c.id=a.child_id JOIN families f ON f.id=c.family_id WHERE f.campus_id=? AND ss.service_date=? AND a.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP')");$presence->execute([$actor['campus_id'],$currentSunday]);$present=(int)$presence->fetchColumn();}api_ok(['registeredChildren'=>$registered,'active'=>(int)($row['active']??0),'presentThisSunday'=>$present,'male'=>(int)($row['male']??0),'female'=>(int)($row['female']??0),'currentSundayDate'=>$currentSunday]);
}
function api_directory_month(): array {
    $month=trim((string)($_GET['month']??''));
    if (!preg_match('/^\d{4}-\d{2}$/',$month)) $month=(new DateTimeImmutable('now',new DateTimeZone('Africa/Lagos')))->format('Y-m');
    $start=DateTimeImmutable::createFromFormat('!Y-m',$month,new DateTimeZone('Africa/Lagos'));
    if(!$start) $start=new DateTimeImmutable('first day of this month',new DateTimeZone('Africa/Lagos'));
    return [$start->format('Y-m'),$start->format('Y-m-01'),$start->modify('+1 month')->format('Y-m-01')];
}
function api_directory_attendance(PDO $db,array $childIds,string $start,string $end): array {
    if(!$childIds) return [[],[]];
    $marks=implode(',',array_fill(0,count($childIds),'?'));
    $sessions=$db->prepare("SELECT DISTINCT ss.service_date FROM service_sessions ss WHERE ss.service_date>=? AND ss.service_date<? ORDER BY ss.service_date DESC LIMIT 5");
    $sessions->execute([$start,$end]);$dates=array_column($sessions->fetchAll(),'service_date');
    $present=$db->prepare("SELECT a.child_id,ss.service_date FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id WHERE a.child_id IN ($marks) AND ss.service_date>=? AND ss.service_date<? AND a.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP') GROUP BY a.child_id,ss.service_date");
    $present->execute(array_merge($childIds,[$start,$end]));$map=[];
    foreach($present->fetchAll() as $row)$map[(int)$row['child_id']][(string)$row['service_date']]=true;
    return [$dates,$map];
}
function api_latest_completed_sunday(PDO $db,int $campusId): ?string {
    $s=$db->prepare("SELECT MAX(service_date) FROM service_sessions WHERE campus_id=? AND service_type IN ('FIRST_SERVICE','SECOND_SERVICE') AND service_date<=CURDATE()");
    $s->execute([$campusId]);$date=$s->fetchColumn();return $date?:null;
}
function api_sunday_presence(PDO $db,array $childIds,?string $serviceDate): array {
    if(!$childIds||!$serviceDate)return [];
    $marks=implode(',',array_fill(0,count($childIds),'?'));
    $s=$db->prepare("SELECT DISTINCT a.child_id FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id WHERE a.child_id IN ($marks) AND ss.service_date=? AND a.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP')");
    $s->execute(array_merge($childIds,[$serviceDate]));$present=[];
    foreach($s->fetchAll() as $row)$present[(int)$row['child_id']]=true;
    return $present;
}
function api_child_allowed(PDO $db, array $actor, int $id, bool $sharedView = false): array {
    $s=$db->prepare('SELECT '.api_child_select().' FROM children c JOIN families f ON f.id=c.family_id LEFT JOIN classes cl ON cl.id=c.class_id WHERE c.id=? LIMIT 1'); $s->execute([$id]); $child=$s->fetch();
    if (!$child) api_error('CHILD_NOT_FOUND','Child not found.',404);
    $allowed=$sharedView?null:api_permitted_class_ids($db,$actor); if ($allowed !== null && (!in_array((int)$child['classId'],$allowed,true))) api_error('FORBIDDEN','This child is outside your assigned classes.',403);
    return $child;
}
function api_list_campuses(PDO $db): never { api_actor($db); api_ok($db->query('SELECT id,name,code,timezone FROM campuses ORDER BY name')->fetchAll()); }
function api_campus(PDO $db, int $id): never {
    $actor=api_actor($db,api_method()==='PATCH');
    if (api_method()==='GET') { $s=$db->prepare('SELECT id,name,code,timezone FROM campuses WHERE id=?'); $s->execute([$id]); $row=$s->fetch(); if(!$row) api_error('CAMPUS_NOT_FOUND','Campus not found.',404); api_ok($row); }
    $v=api_input(); $allowed=array_intersect_key($v,array_flip(['name','code','timezone'])); if(!$allowed) api_error('VALIDATION_ERROR','No editable campus fields were supplied.',422);
    $set=[];$params=[]; foreach($allowed as $key=>$value){$set[]="$key=?";$params[]=$value;} $params[]=$id; $db->prepare('UPDATE campuses SET '.implode(',',$set).' WHERE id=?')->execute($params); api_audit($db,$actor,'CAMPUS_UPDATED','Campus',$id,$allowed); api_ok(['id'=>$id,'updated'=>true]);
}
function api_list_classes(PDO $db): never {
    $actor=api_actor($db); $allowed=null; $where=['c.is_active=1'];$params=[];
    if(isset($_GET['campusId'])){$where[]='c.campus_id=?';$params[]=(int)$_GET['campusId'];}
    if($allowed!==null){if(!$allowed)api_ok([]);$where[]='c.id IN ('.implode(',',array_fill(0,count($allowed),'?')).')';$params=array_merge($params,$allowed);}
    $s=$db->prepare('SELECT c.id,c.campus_id AS campusId,c.name,c.min_age AS minAge,c.max_age AS maxAge,c.age_label AS ageLabel,c.display_order AS displayOrder,c.is_active AS active FROM classes c WHERE '.implode(' AND ',$where).' ORDER BY c.display_order,c.name');$s->execute($params);api_ok($s->fetchAll());
}
function api_class(PDO $db,int $id): never {
    $actor=api_actor($db,api_method()!=='GET'); if(api_method()==='GET'){ $s=$db->prepare('SELECT id,campus_id AS campusId,name,min_age AS minAge,max_age AS maxAge,age_label AS ageLabel,display_order AS displayOrder,is_active AS active FROM classes WHERE id=?');$s->execute([$id]);$row=$s->fetch();if(!$row)api_error('CLASS_NOT_FOUND','Class not found.',404);api_ok($row); }
    $v=api_input();$allowed=array_intersect_key($v,array_flip(['name','minAge','maxAge','ageLabel','displayOrder','active']));if(!$allowed)api_error('VALIDATION_ERROR','No editable class fields were supplied.',422);$map=['minAge'=>'min_age','maxAge'=>'max_age','ageLabel'=>'age_label','displayOrder'=>'display_order','active'=>'is_active'];$sets=[];$params=[];foreach($allowed as $k=>$value){$sets[]=($map[$k]??$k).'=?';$params[]=$value;}$params[]=$id;$db->prepare('UPDATE classes SET '.implode(',',$sets).' WHERE id=?')->execute($params);api_audit($db,$actor,'CLASS_UPDATED','Class',$id,$allowed);api_ok(['id'=>$id,'updated'=>true]);
}
function api_classroom_service(PDO $db,array $actor): ?array {
    $id=(int)($_GET['serviceSessionId']??0);$sql='SELECT id,name,service_type AS serviceType,service_date AS serviceDate,starts_at AS startsAt FROM service_sessions WHERE campus_id=?'.($id?' AND id=?':' AND service_type IN (\'FIRST_SERVICE\',\'SECOND_SERVICE\')').' ORDER BY service_date DESC,starts_at DESC LIMIT 1';$s=$db->prepare($sql);$s->execute($id?[(int)$actor['campus_id'],$id]:[(int)$actor['campus_id']]);$row=$s->fetch();if($id&&!$row)api_error('SERVICE_SESSION_NOT_FOUND','This service is not available for your campus.',404);return $row?:null;
}
function api_classroom_allowed(PDO $db,array $actor,int $classId,bool $sharedView = false): array {
    $allowed=$sharedView?null:api_permitted_class_ids($db,$actor);if($allowed!==null&&!in_array($classId,$allowed,true))api_error('FORBIDDEN','This classroom is outside your permitted assignments.',403);$s=$db->prepare('SELECT id,campus_id AS campusId,name,age_label AS ageLabel,min_age AS minAge,max_age AS maxAge,is_active AS active FROM classes WHERE id=? AND campus_id=?');$s->execute([$classId,(int)$actor['campus_id']]);$class=$s->fetch();if(!$class)api_error('CLASS_NOT_FOUND','This classroom was not found.',404);return $class;
}
function api_can_manage_classroom(PDO $db,array $actor,int $classId,?int $sessionId): bool {
    if($actor['access_level']==='TPK_SUPER_ADMIN')return true;if(api_table_exists($db,'roster_assignments')){$s=$db->prepare('SELECT 1 FROM roster_assignments WHERE user_id=? AND class_id=? AND status NOT IN (\'CANCELLED\',\'REPLACED\')'.($sessionId?' AND service_session_id=?':'').' LIMIT 1');$s->execute($sessionId?[(int)$actor['id'],$classId,$sessionId]:[(int)$actor['id'],$classId]);if($s->fetchColumn())return true;}if(!api_table_exists($db,'staff_class_assignments'))return false;$s=$db->prepare('SELECT 1 FROM staff_class_assignments WHERE staff_user_id=? AND class_id=? AND is_active=1 LIMIT 1');$s->execute([(int)$actor['id'],$classId]);return(bool)$s->fetchColumn();
}
function api_classroom_teachers(PDO $db,int $classId,?array $service): array {
    $sessionId=(int)($service['id']??0);
    $serviceDate=(string)($service['serviceDate']??'');
    $serviceType=(string)($service['serviceType']??'');
    if(api_table_exists($db,'roster_assignments')&&api_table_exists($db,'duty_types')){
        // Prefer the precise selected session. Older data can contain duplicate
        // sessions for one Sunday, so fall back to the same date and service type.
        $sql="SELECT MIN(ra.id) AS assignmentId,ra.user_id AS userId,MAX(ra.status) AS status,MAX(ra.confirmed_at) AS confirmedAt,MIN(dt.name) AS dutyName,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,''),' ',COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))),''),u.name) AS name,p.profile_image_url AS profileImageUrl,p.whatsapp_number AS whatsappNumber,p.mobile_number AS mobileNumber FROM roster_assignments ra JOIN duty_types dt ON dt.id=ra.duty_type_id JOIN staff_users u ON u.id=ra.user_id LEFT JOIN teacher_profiles p ON p.staff_user_id=u.id LEFT JOIN service_sessions ss ON ss.id=ra.service_session_id WHERE ra.class_id=? AND ra.status NOT IN ('CANCELLED','REPLACED') AND (ra.service_session_id=? OR (?<>'' AND ra.assignment_date=? AND ss.service_type=?)) GROUP BY ra.user_id,u.name,p.title,p.first_name,p.last_name,p.profile_image_url,p.whatsapp_number,p.mobile_number ORDER BY MAX(ra.status)='PRESENT' DESC,MIN(ra.id)";
        $s=$db->prepare($sql);$s->execute([$classId,$sessionId,$serviceDate,$serviceDate,$serviceType]);$rostered=$s->fetchAll();
        if($rostered)return $rostered;
    }
    // A current class assignment is the intentional fallback when a roster has
    // not yet been published for the selected service.
    if(!api_table_exists($db,'staff_class_assignments'))return [];
    $s=$db->prepare("SELECT NULL AS assignmentId,sca.staff_user_id AS userId,'ASSIGNED' AS status,NULL AS confirmedAt,'Class teacher' AS dutyName,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,''),' ',COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))),''),u.name) AS name,p.profile_image_url AS profileImageUrl,p.whatsapp_number AS whatsappNumber,p.mobile_number AS mobileNumber FROM staff_class_assignments sca JOIN staff_users u ON u.id=sca.staff_user_id LEFT JOIN teacher_profiles p ON p.staff_user_id=u.id WHERE sca.class_id=? AND sca.is_active=1 AND u.is_active=1 ORDER BY u.name");$s->execute([$classId]);return $s->fetchAll();
}
function api_classrooms(PDO $db): never {
    $actor=api_actor($db);$service=api_classroom_service($db,$actor);$sessionId=(int)($service['id']??0);$allowed=null;$where=['c.campus_id=?','c.is_active=1'];$params=[(int)$actor['campus_id']];if($allowed!==null){if(!$allowed)api_ok(['serviceSession'=>$service,'summary'=>['activeClasses'=>0,'checkedIn'=>0,'teachersAssigned'=>0,'needsAttention'=>0],'items'=>[]]);$where[]='c.id IN ('.implode(',',array_fill(0,count($allowed),'?')).')';$params=array_merge($params,$allowed);}if(($classId=(int)($_GET['classId']??0))>0){$where[]='c.id=?';$params[]=$classId;}if(($q=trim((string)($_GET['search']??'')))!==''){$where[]='(c.name LIKE ? OR EXISTS(SELECT 1 FROM children sc WHERE sc.class_id=c.id AND CONCAT(sc.first_name,\' \',sc.last_name) LIKE ?) OR EXISTS(SELECT 1 FROM roster_assignments sra JOIN staff_users su ON su.id=sra.user_id WHERE sra.class_id=c.id AND sra.service_session_id=? AND su.name LIKE ?))';$params=array_merge($params,["%$q%","%$q%",$sessionId,"%$q%"]);}
    $s=$db->prepare('SELECT c.id,c.name,c.age_label AS ageLabel,c.min_age AS minAge,c.max_age AS maxAge,COUNT(ch.id) AS registered FROM classes c LEFT JOIN children ch ON ch.class_id=c.id AND ch.is_active=1 WHERE '.implode(' AND ',$where).' GROUP BY c.id,c.name,c.age_label,c.min_age,c.max_age ORDER BY c.display_order,c.name');$s->execute($params);$items=[];$checked=0;$teachers=0;$attention=0;foreach($s->fetchAll() as $row){$classId=(int)$row['id'];$registered=(int)$row['registered'];$present=0;if($sessionId){$a=$db->prepare("SELECT COUNT(*) FROM attendance WHERE service_session_id=? AND class_id=? AND status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP')");$a->execute([$sessionId,$classId]);$present=(int)$a->fetchColumn();}$row['registered']=$registered;$row['present']=$present;$row['absent']=$service?max(0,$registered-$present):0;$row['attendancePercentage']=$registered?(int)round($present/$registered*100):0;$row['teachers']=api_classroom_teachers($db,$classId,$service);$row['teacherCount']=count($row['teachers']);$profile=$db->prepare("SELECT COUNT(*) FROM children c LEFT JOIN child_guardians cg ON cg.child_id=c.id AND cg.is_primary=1 LEFT JOIN guardians g ON g.id=cg.guardian_id WHERE c.class_id=? AND c.is_active=1 AND (c.date_of_birth IS NULL OR c.gender IS NULL OR g.id IS NULL OR g.phone IS NULL OR g.phone='')");$profile->execute([$classId]);$incomplete=(int)$profile->fetchColumn();$unconfirmed=count(array_filter($row['teachers'],fn($t)=>$t['status']!=='PRESENT'));$row['attentionCount']=$incomplete+$unconfirmed+(!$row['teacherCount']?1:0);$row['status']=!$row['teacherCount']?'NO_TEACHER_ASSIGNED':($row['attentionCount']?'NEEDS_ATTENTION':'RUNNING_SMOOTHLY');$items[]=$row;$checked+=$present;$teachers+=$row['teacherCount'];$attention+=$row['attentionCount'];}
    if(($status=trim((string)($_GET['status']??'')))!=='')$items=array_values(array_filter($items,fn($row)=>$row['status']===$status));api_ok(['serviceSession'=>$service,'summary'=>['activeClasses'=>count($items),'checkedIn'=>$checked,'teachersAssigned'=>$teachers,'needsAttention'=>$attention],'items'=>$items]);
}
function api_classroom_detail(PDO $db,int $classId): never {
    if(!api_table_exists($db,'classroom_assignments')||!api_table_exists($db,'classroom_assignment_submissions')||!api_table_exists($db,'classroom_notes')||!api_table_exists($db,'roster_assignments')||!api_table_exists($db,'duty_types')){
        $actor=api_actor($db);$class=api_classroom_allowed($db,$actor,$classId,true);$service=api_classroom_service($db,$actor);$sessionId=(int)($service['id']??0);$children=$db->prepare("SELECT c.id,c.first_name AS firstName,c.last_name AS lastName,c.date_of_birth AS dateOfBirth,DATE(f.created_at) AS joinedAt,TRIM(CONCAT(COALESCE(g.first_name,''),' ',COALESCE(g.last_name,''))) AS guardianName,g.id AS guardianId,g.phone AS guardianPhone,CASE WHEN a.id IS NULL THEN 'ABSENT' ELSE 'PRESENT' END AS todayStatus FROM children c JOIN families f ON f.id=c.family_id LEFT JOIN child_guardians cg ON cg.child_id=c.id AND cg.is_primary=1 LEFT JOIN guardians g ON g.id=cg.guardian_id LEFT JOIN attendance a ON a.child_id=c.id AND a.service_session_id=? AND a.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP') WHERE c.class_id=? AND c.is_active=1 ORDER BY c.first_name,c.last_name");$children->execute([$sessionId?:0,$classId]);$rows=$children->fetchAll();foreach($rows as &$row){$row['age']=api_child_age($row['dateOfBirth']);$row['assignmentStatus']='—';}unset($row);$present=count(array_filter($rows,fn($r)=>$r['todayStatus']==='PRESENT'));[$resolved,$start,$end]=api_directory_month();api_ok(['class'=>$class,'serviceSession'=>$service,'canManage'=>false,'isSuperAdmin'=>$actor['access_level']==='TPK_SUPER_ADMIN','teachers'=>[],'children'=>$rows,'summary'=>['present'=>$present,'absent'=>max(0,count($rows)-$present),'registered'=>count($rows)],'assignment'=>null,'monthly'=>['month'=>$resolved,'sessions'=>[],'presentByDate'=>[]],'notes'=>[],'weeklyReviews'=>[]]);
    }
    $actor=api_actor($db);$class=api_classroom_allowed($db,$actor,$classId,true);$service=api_classroom_service($db,$actor);$sessionId=(int)($service['id']??0);$teachers=api_classroom_teachers($db,$classId,$service);$assignment=null;if($sessionId){$as=$db->prepare('SELECT ca.id,ca.title,ca.instructions,ca.date_given AS dateGiven,ca.due_date AS dueDate,ca.resource_url AS resourceUrl,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,\'\'),\' \',COALESCE(p.first_name,\'\'),\' \',COALESCE(p.last_name,\'\'))),\'\'),u.name) AS createdBy FROM classroom_assignments ca JOIN staff_users u ON u.id=ca.created_by_staff_user_id LEFT JOIN teacher_profiles p ON p.staff_user_id=u.id WHERE ca.class_id=? AND ca.service_session_id=? ORDER BY ca.id DESC LIMIT 1');$as->execute([$classId,$sessionId]);$assignment=$as->fetch()?:null;}
    $children=$db->prepare("SELECT c.id,c.first_name AS firstName,c.last_name AS lastName,c.date_of_birth AS dateOfBirth,COALESCE(c.joined_at,DATE(f.created_at)) AS joinedAt,TRIM(CONCAT(COALESCE(g.first_name,''),' ',COALESCE(g.last_name,''))) AS guardianName,g.id AS guardianId,g.phone AS guardianPhone,CASE WHEN a.id IS NULL THEN 'ABSENT' ELSE 'PRESENT' END AS todayStatus FROM children c JOIN families f ON f.id=c.family_id LEFT JOIN child_guardians cg ON cg.child_id=c.id AND cg.is_primary=1 LEFT JOIN guardians g ON g.id=cg.guardian_id LEFT JOIN attendance a ON a.child_id=c.id AND a.service_session_id=? AND a.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP') WHERE c.class_id=? AND c.is_active=1 ORDER BY c.first_name,c.last_name");$children->execute([$sessionId?:0,$classId]);$rows=$children->fetchAll();foreach($rows as &$row){$row['age']=api_child_age($row['dateOfBirth']);$row['assignmentStatus']='—';if($assignment){if($row['todayStatus']==='ABSENT')$row['assignmentStatus']='NOT_IN_CLASS';else{$sub=$db->prepare('SELECT status FROM classroom_assignment_submissions WHERE assignment_id=? AND child_id=?');$sub->execute([(int)$assignment['id'],(int)$row['id']]);$row['assignmentStatus']=$sub->fetchColumn()?:'NOT_SUBMITTED';}}}unset($row);$present=count(array_filter($rows,fn($r)=>$r['todayStatus']==='PRESENT'));
    if($assignment){$assignment['submittedCount']=count(array_filter($rows,fn($r)=>$r['assignmentStatus']==='SUBMITTED'));$assignment['pendingCount']=count(array_filter($rows,fn($r)=>$r['assignmentStatus']==='NOT_SUBMITTED'));}$month=trim((string)($_GET['month']??date('Y-m')));[$resolved,$start,$end]=api_directory_month();$ms=$db->prepare("SELECT id,service_date AS serviceDate FROM service_sessions WHERE campus_id=? AND service_type=? AND service_date>=? AND service_date<? AND service_date<=CURDATE() ORDER BY service_date");$ms->execute([(int)$actor['campus_id'],$service['serviceType']??'SECOND_SERVICE',$start,$end]);$sessions=$ms->fetchAll();$matrix=[];foreach($sessions as $week){$a=$db->prepare("SELECT child_id FROM attendance WHERE service_session_id=? AND status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP')");$a->execute([(int)$week['id']]);$matrix[(string)$week['serviceDate']]=array_map('intval',array_column($a->fetchAll(),'child_id'));}$notes=$db->prepare("SELECT n.id,n.note,n.created_at AS createdAt,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,''),' ',COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))),''),u.name) AS author FROM classroom_notes n JOIN staff_users u ON u.id=n.created_by_staff_user_id LEFT JOIN teacher_profiles p ON p.staff_user_id=u.id WHERE n.class_id=? AND (n.service_session_id=? OR n.service_session_id IS NULL) ORDER BY n.created_at DESC");$notes->execute([$classId,$sessionId?:0]);
    $reviews=[];if(api_table_exists($db,'classroom_weekly_reviews')){$review=$db->prepare("SELECT r.id,r.service_session_id AS serviceSessionId,ss.service_date AS serviceDate,ss.name AS serviceName,r.worked_well AS workedWell,r.needs_improvement AS needsImprovement,r.created_at AS createdAt,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,''),' ',COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))),''),u.name) AS author FROM classroom_weekly_reviews r JOIN service_sessions ss ON ss.id=r.service_session_id JOIN staff_users u ON u.id=r.created_by_staff_user_id LEFT JOIN teacher_profiles p ON p.staff_user_id=u.id WHERE r.class_id=? AND ss.service_date>=? AND ss.service_date<? ORDER BY ss.service_date DESC,r.created_at DESC");$review->execute([$classId,$start,$end]);$reviews=$review->fetchAll();}
    api_ok(['class'=>$class,'serviceSession'=>$service,'canManage'=>api_can_manage_classroom($db,$actor,$classId,$sessionId?:null),'isSuperAdmin'=>$actor['access_level']==='TPK_SUPER_ADMIN','teachers'=>$teachers,'children'=>$rows,'summary'=>['present'=>$present,'absent'=>max(0,count($rows)-$present),'registered'=>count($rows)],'assignment'=>$assignment,'monthly'=>['month'=>$resolved,'sessions'=>$sessions,'presentByDate'=>$matrix],'notes'=>$notes->fetchAll(),'weeklyReviews'=>$reviews]);
}
function api_create_classroom_assignment(PDO $db,int $classId): never {$actor=api_actor($db);$class=api_classroom_allowed($db,$actor,$classId);$v=api_input();$sessionId=(int)($v['serviceSessionId']??0);if(!api_can_manage_classroom($db,$actor,$classId,$sessionId?:null))api_error('FORBIDDEN','You are not assigned to manage this classroom.',403);$title=trim((string)($v['title']??''));if($title==='')api_error('VALIDATION_ERROR','Assignment title is required.',422);$session=null;if($sessionId){$lookup=$db->prepare('SELECT service_date AS serviceDate FROM service_sessions WHERE id=? AND campus_id=?');$lookup->execute([$sessionId,(int)$actor['campus_id']]);$session=$lookup->fetch();if(!$session)api_error('SERVICE_SESSION_NOT_FOUND','This service is not available for your campus.',404);}$date=trim((string)($v['dateGiven']??($session['serviceDate']??date('Y-m-d'))));$s=$db->prepare('INSERT INTO classroom_assignments(campus_id,class_id,service_session_id,date_given,due_date,title,instructions,resource_url,created_by_staff_user_id) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([(int)$class['campusId'],$classId,$sessionId?:null,$date,trim((string)($v['dueDate']??''))?:null,$title,trim((string)($v['instructions']??''))?:null,trim((string)($v['resourceUrl']??''))?:null,(int)$actor['id']]);$id=(int)$db->lastInsertId();api_audit($db,$actor,'CLASSROOM_ASSIGNMENT_CREATED','ClassroomAssignment',$id,['classId'=>$classId,'serviceSessionId'=>$sessionId]);api_ok(['id'=>$id],201);}
function api_submission(PDO $db,int $assignmentId,int $childId): never {$actor=api_actor($db);$v=api_input();$lookup=$db->prepare('SELECT ca.class_id AS classId,ca.service_session_id AS serviceSessionId FROM classroom_assignments ca WHERE ca.id=?');$lookup->execute([$assignmentId]);$assignment=$lookup->fetch();if(!$assignment)api_error('ASSIGNMENT_NOT_FOUND','This assignment was not found.',404);api_classroom_allowed($db,$actor,(int)$assignment['classId']);if(!api_can_manage_classroom($db,$actor,(int)$assignment['classId'],(int)$assignment['serviceSessionId']))api_error('FORBIDDEN','You are not assigned to update this assignment.',403);$status=strtoupper(trim((string)($v['status']??'')));if(!in_array($status,['SUBMITTED','NOT_SUBMITTED','EXCUSED'],true))api_error('VALIDATION_ERROR','Choose a valid submission status.',422);$s=$db->prepare('INSERT INTO classroom_assignment_submissions(assignment_id,child_id,status,updated_by_staff_user_id) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),updated_by_staff_user_id=VALUES(updated_by_staff_user_id)');$s->execute([$assignmentId,$childId,$status,(int)$actor['id']]);api_ok(['assignmentId'=>$assignmentId,'childId'=>$childId,'status'=>$status]);}
function api_create_classroom_note(PDO $db,int $classId): never {$actor=api_actor($db);$class=api_classroom_allowed($db,$actor,$classId);$v=api_input();$sessionId=(int)($v['serviceSessionId']??0);if(!api_can_manage_classroom($db,$actor,$classId,$sessionId?:null))api_error('FORBIDDEN','You are not assigned to add notes for this classroom.',403);$note=trim((string)($v['note']??''));if($note==='')api_error('VALIDATION_ERROR','Enter a class note.',422);$s=$db->prepare('INSERT INTO classroom_notes(campus_id,class_id,service_session_id,note,created_by_staff_user_id) VALUES(?,?,?,?,?)');$s->execute([(int)$class['campusId'],$classId,$sessionId?:null,$note,(int)$actor['id']]);api_ok(['id'=>(int)$db->lastInsertId()],201);}
function api_create_classroom_weekly_review(PDO $db,int $classId): never {$actor=api_actor($db);if(!api_table_exists($db,'classroom_weekly_reviews'))api_error('FEATURE_UNAVAILABLE','Weekly review storage is not ready yet.',503);$class=api_classroom_allowed($db,$actor,$classId);$v=api_input();$sessionId=(int)($v['serviceSessionId']??0);if(!$sessionId)api_error('VALIDATION_ERROR','Choose the Sunday this review is for.',422);$service=$db->prepare("SELECT id FROM service_sessions WHERE id=? AND campus_id=? AND service_type IN ('FIRST_SERVICE','SECOND_SERVICE')");$service->execute([$sessionId,(int)$actor['campus_id']]);if(!$service->fetch())api_error('SERVICE_SESSION_NOT_FOUND','That Sunday service is not available.',404);if(!api_can_manage_classroom($db,$actor,$classId,$sessionId))api_error('FORBIDDEN','Only teachers assigned to this class for that Sunday can add its review.',403);$worked=trim((string)($v['workedWell']??''));$improve=trim((string)($v['needsImprovement']??''));if($worked===''&&$improve==='')api_error('VALIDATION_ERROR','Add what worked or what needs improvement.',422);$s=$db->prepare('INSERT INTO classroom_weekly_reviews(campus_id,class_id,service_session_id,worked_well,needs_improvement,created_by_staff_user_id) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE worked_well=VALUES(worked_well),needs_improvement=VALUES(needs_improvement),updated_at=CURRENT_TIMESTAMP');$s->execute([(int)$class['campusId'],$classId,$sessionId,$worked?:null,$improve?:null,(int)$actor['id']]);api_audit($db,$actor,'CLASSROOM_WEEKLY_REVIEW_SAVED','Classroom',$classId,['serviceSessionId'=>$sessionId]);api_ok(['saved'=>true]);}
function api_create_class(PDO $db): never { $actor=api_actor($db,true);$v=api_input();foreach(['campusId','name','ageLabel'] as $key)if(empty($v[$key]))api_error('VALIDATION_ERROR',"$key is required.",422);$s=$db->prepare('INSERT INTO classes(campus_id,name,age_label,min_age,max_age,display_order) VALUES(?,?,?,?,?,?)');$s->execute([(int)$v['campusId'],$v['name'],$v['ageLabel'],$v['minAge']??null,$v['maxAge']??null,$v['displayOrder']??999]);$id=(int)$db->lastInsertId();api_audit($db,$actor,'CLASS_CREATED','Class',$id);api_ok(['id'=>$id],201); }
function api_list_children(PDO $db): never {
    $actor=api_actor($db);[$page,$limit,$offset]=api_page();$where=[];$params=[];$allowed=null;$currentSunday=api_latest_completed_sunday($db,(int)$actor['campus_id']);
    if($allowed!==null){if(!$allowed)api_ok([],200,['page'=>$page,'limit'=>$limit,'total'=>0,'totalPages'=>1]);$where[]='c.class_id IN ('.implode(',',array_fill(0,count($allowed),'?')).')';$params=array_merge($params,$allowed);}
    if(($q=trim((string)($_GET['search']??'')))!==''){$where[]='(c.first_name LIKE ? OR c.last_name LIKE ? OR EXISTS (SELECT 1 FROM child_guardians search_cg JOIN guardians search_g ON search_g.id=search_cg.guardian_id WHERE search_cg.child_id=c.id AND (search_g.first_name LIKE ? OR search_g.last_name LIKE ? OR search_g.phone LIKE ?)))';$params=array_merge($params,["%$q%","%$q%","%$q%","%$q%","%$q%"]);}
    $where[]='f.campus_id=?';$params[]=$actor['campus_id'];
    foreach(['classId'=>'c.class_id','gender'=>'c.gender'] as $query=>$column)if(isset($_GET[$query])&&$_GET[$query]!==''){$where[]="$column=?";$params[]=$_GET[$query];}
    if(isset($_GET['visitType'])&&$_GET['visitType']!==''){$attendanceBefore=$currentSunday?"EXISTS(SELECT 1 FROM attendance va JOIN service_sessions vs ON vs.id=va.service_session_id WHERE va.child_id=c.id AND va.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP') AND vs.service_date<?)":"EXISTS(SELECT 1 FROM attendance va WHERE va.child_id=c.id AND va.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP'))";$where[]=strtoupper((string)$_GET['visitType'])==='FIRST_TIMER'?"NOT ($attendanceBefore)":$attendanceBefore;if($currentSunday)$params[]=$currentSunday;}
    if(isset($_GET['active'])){$where[]='c.is_active=?';$params[]=filter_var($_GET['active'],FILTER_VALIDATE_BOOLEAN)?1:0;}
    if(isset($_GET['classAssignmentRequired'])){$where[]='c.class_assignment_required=?';$params[]=filter_var($_GET['classAssignmentRequired'],FILTER_VALIDATE_BOOLEAN)?1:0;}
    if(isset($_GET['ageMin'])&&$_GET['ageMin']!==''){$where[]='TIMESTAMPDIFF(YEAR,c.date_of_birth,CURDATE())>=?';$params[]=(int)$_GET['ageMin'];}
    if(isset($_GET['ageMax'])&&$_GET['ageMax']!==''){$where[]='TIMESTAMPDIFF(YEAR,c.date_of_birth,CURDATE())<=?';$params[]=(int)$_GET['ageMax'];}
    $profile=trim((string)($_GET['profileStatus']??''));
    $completeSql="c.date_of_birth IS NOT NULL AND c.gender IS NOT NULL AND c.class_id IS NOT NULL AND pg.id IS NOT NULL AND pg.phone IS NOT NULL AND pg.phone<>''";
    if($profile==='complete')$where[]=$completeSql;
    if($profile==='needs_info')$where[]="NOT ($completeSql)";
    $filter=$where?' WHERE '.implode(' AND ',$where):'';$sort=['id'=>'c.id','name'=>'c.first_name','firstName'=>'c.first_name','lastName'=>'c.last_name','dateOfBirth'=>'c.date_of_birth','age'=>'TIMESTAMPDIFF(YEAR,c.date_of_birth,CURDATE())','class'=>'cl.name','classId'=>'c.class_id','gender'=>'c.gender','guardian'=>'pg.first_name','lastAttended'=>'lastAttended'][$_GET['sort']??'name']??'c.first_name';$order=strtolower((string)($_GET['order']??'asc'))==='desc'?'DESC':'ASC';
    $countFilter=str_replace('pg.id','(SELECT cg.guardian_id FROM child_guardians cg WHERE cg.child_id=c.id AND cg.is_primary=1 LIMIT 1)',$filter);$countFilter=str_replace('pg.phone',"(SELECT g.phone FROM child_guardians cg JOIN guardians g ON g.id=cg.guardian_id WHERE cg.child_id=c.id AND cg.is_primary=1 LIMIT 1)",$countFilter);
    $count=$db->prepare("SELECT COUNT(*) FROM children c JOIN families f ON f.id=c.family_id$countFilter");$count->execute($params);$total=(int)$count->fetchColumn();
    $sql="SELECT ".api_child_select().",f.surname AS familySurname,f.family_code AS familyCode,
      pg.id AS guardianId,TRIM(CONCAT(COALESCE(pg.first_name,''),' ',COALESCE(pg.last_name,''))) AS guardianName,pg.phone AS guardianPhone,
      COALESCE(links.guardianNames,'—') AS guardianNames,COALESCE(links.guardianPhones,'—') AS guardianPhones,
      (SELECT MAX(ss.service_date) FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id WHERE a.child_id=c.id AND a.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP')) AS lastAttended,
      COALESCE(pickups.authorisedPickupNames,'No additional authorised pickup') AS authorisedPickupNames
      FROM children c JOIN families f ON f.id=c.family_id LEFT JOIN classes cl ON cl.id=c.class_id
      LEFT JOIN child_guardians pcg ON pcg.child_id=c.id AND pcg.is_primary=1 LEFT JOIN guardians pg ON pg.id=pcg.guardian_id
      LEFT JOIN (SELECT cg.child_id,GROUP_CONCAT(DISTINCT TRIM(CONCAT(g.first_name,' ',g.last_name)) ORDER BY cg.is_primary DESC,g.first_name SEPARATOR ' · ') AS guardianNames,GROUP_CONCAT(DISTINCT g.phone ORDER BY cg.is_primary DESC,g.first_name SEPARATOR ' · ') AS guardianPhones FROM child_guardians cg JOIN guardians g ON g.id=cg.guardian_id GROUP BY cg.child_id) links ON links.child_id=c.id
      LEFT JOIN (SELECT family_id,GROUP_CONCAT(DISTINCT TRIM(CONCAT(first_name,' ',last_name)) ORDER BY first_name SEPARATOR ' · ') AS authorisedPickupNames FROM authorized_pickups WHERE is_active=1 GROUP BY family_id) pickups ON pickups.family_id=c.family_id$filter ORDER BY $sort $order,c.last_name LIMIT $limit OFFSET $offset";
    $s=$db->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$childIds=array_map(fn($row)=>(int)$row['id'],$rows);[$month,$start,$end]=api_directory_month();[$dates,$present]=api_directory_attendance($db,$childIds,$start,$end);$thisSundayPresent=api_sunday_presence($db,$childIds,$currentSunday);
    foreach($rows as &$row){$childId=(int)$row['id'];$row['age']=api_child_age($row['dateOfBirth']);$row['sundaysPresent']=count($present[$childId]??[]);$row['attendanceDates']=$dates;$row['attendancePresentDates']=array_keys($present[$childId]??[]);}unset($row);
    api_ok($rows,200,['page'=>$page,'limit'=>$limit,'total'=>$total,'totalPages'=>max(1,(int)ceil($total/$limit)),'month'=>$month,'attendanceDates'=>$dates,'currentSundayDate'=>$currentSunday]);
}
function api_child(PDO $db,int $id): never {
    $actor=api_actor($db,api_method()==='PATCH');$child=api_child_allowed($db,$actor,$id,api_method()==='GET');
    if(api_method()==='GET'){
        $care=$db->prepare('SELECT 1 FROM child_care_profiles WHERE child_id=?');$care->execute([$id]);$child['careInformationAvailable']=(bool)$care->fetchColumn();$child['age']=api_child_age($child['dateOfBirth']);$currentSunday=api_latest_completed_sunday($db,(int)$actor['campus_id']);$prior=$db->prepare("SELECT 1 FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id WHERE a.child_id=? AND a.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP')".($currentSunday?" AND ss.service_date<?":"")." LIMIT 1");$prior->execute($currentSunday?[$id,$currentSunday]:[$id]);$child['visitType']=$prior->fetchColumn()?'RETURNING':'FIRST_TIMER';$child['currentSundayDate']=$currentSunday;$today=api_sunday_presence($db,[$id],$currentSunday);$child['currentSundayStatus']=!$currentSunday||empty($child['joinedAt'])||$child['joinedAt']>$currentSunday?'NOT_EXPECTED':(!empty($today[$id])?'PRESENT':'ABSENT');
        $guards=$db->prepare('SELECT g.id,g.first_name AS firstName,g.last_name AS lastName,g.phone AS primaryPhone,g.secondary_phone AS secondaryPhone,g.email,cg.relationship,cg.is_primary AS `primary`,cg.authorised_pickup AS authorisedPickup FROM child_guardians cg JOIN guardians g ON g.id=cg.guardian_id WHERE cg.child_id=? ORDER BY cg.is_primary DESC,g.first_name');$guards->execute([$id]);$child['guardians']=$guards->fetchAll();$child['guardianId']=$child['guardians'][0]['id']??null;$child['guardianPhone']=$child['guardians'][0]['primaryPhone']??null;
        $pickups=$db->prepare('SELECT id,first_name AS firstName,last_name AS lastName,phone,relationship FROM authorized_pickups WHERE family_id=? AND is_active=1 ORDER BY first_name');$pickups->execute([$child['familyId']]);$child['authorisedPickups']=$pickups->fetchAll();
        $history=$db->prepare("SELECT ss.service_date AS serviceDate,ss.name AS serviceName,a.status,a.checked_in_at AS checkedInAt FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id WHERE a.child_id=? ORDER BY ss.service_date DESC LIMIT 12");$history->execute([$id]);$child['attendanceHistory']=$history->fetchAll();$child['lastAttended']=$child['attendanceHistory'][0]['serviceDate']??null;api_ok($child);
    }
    $v=api_input();$fields=['firstName'=>'first_name','lastName'=>'last_name','dateOfBirth'=>'date_of_birth','gender'=>'gender','schoolGrade'=>'school_grade','classId'=>'class_id','active'=>'is_active','classAssignmentRequired'=>'class_assignment_required'];$sets=[];$params=[];foreach($fields as $input=>$column)if(array_key_exists($input,$v)){$sets[]="$column=?";$params[]=$v[$input];}if(!$sets)api_error('VALIDATION_ERROR','No editable child fields were supplied.',422);$params[]=$id;$db->prepare('UPDATE children SET '.implode(',',$sets).' WHERE id=?')->execute($params);api_audit($db,$actor,'CHILD_UPDATED','Child',$id,array_keys($v));api_ok(['id'=>$id,'updated'=>true]);
}
function api_child_attendance(PDO $db,int $id): never {
    $actor=api_actor($db);$child=api_child_allowed($db,$actor,$id,true);[$month,$start,$end]=api_directory_month();
    $records=$db->prepare("SELECT ss.id AS serviceSessionId,ss.service_date AS serviceDate,ss.name AS serviceName,ss.service_type AS serviceType,a.status,a.checked_in_at AS checkedInAt,a.picked_up_at AS pickedUpAt FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id WHERE a.child_id=? AND ss.service_date>=? AND ss.service_date<? ORDER BY ss.service_date DESC,ss.starts_at DESC");$records->execute([$id,$start,$end]);$byDate=[];foreach($records->fetchAll() as $record){if(!isset($byDate[$record['serviceDate']]))$byDate[$record['serviceDate']]=$record;}
    $sessions=$db->prepare("SELECT service_date AS serviceDate,MIN(name) AS serviceName,MIN(service_type) AS serviceType FROM service_sessions WHERE campus_id=? AND service_type IN ('FIRST_SERVICE','SECOND_SERVICE') AND service_date>=? AND service_date<? AND service_date<=CURDATE() GROUP BY service_date ORDER BY service_date DESC");$sessions->execute([(int)$actor['campus_id'],$start,$end]);$joinedAt=(string)($child['joinedAt']??'');$items=[];$present=0;$missed=0;
    foreach($sessions->fetchAll() as $session){if($joinedAt!==''&&$joinedAt>$session['serviceDate'])continue;if(isset($byDate[$session['serviceDate']])){$items[]=$byDate[$session['serviceDate']];$present++;}else{$items[]=['serviceDate'=>$session['serviceDate'],'serviceName'=>$session['serviceName'],'serviceType'=>$session['serviceType'],'status'=>'ABSENT','checkedInAt'=>null,'pickedUpAt'=>null];$missed++;}}
    api_ok(['month'=>$month,'sundaysPresent'=>$present,'sundaysMissed'=>$missed,'items'=>$items]);
}
function api_child_followups(PDO $db,int $id): never {
    $actor=api_actor($db);api_child_allowed($db,$actor,$id,true);try{$s=$db->prepare("SELECT t.id,t.task_type AS taskType,t.status,t.priority,t.notes,t.created_at AS createdAt,t.resolved_at AS resolvedAt,CONCAT(COALESCE(u.name,'')) AS assignedTeacher,ss.service_date AS serviceDate FROM follow_up_tasks t LEFT JOIN staff_users u ON u.id=t.assigned_to_staff_user_id LEFT JOIN service_sessions ss ON ss.id=t.service_session_id WHERE t.child_id=? AND t.campus_id=? ORDER BY t.created_at DESC");$s->execute([$id,$actor['campus_id']]);api_ok($s->fetchAll());}catch(Throwable){api_ok([]);}
}
