function api_guardians(PDO $db): never { $actor=api_actor($db,true);[$page,$limit,$offset]=api_page();$q=trim((string)($_GET['search']??''));$params=[$actor['campus_id']];$filter=' WHERE f.campus_id=?';if($q!==''){$filter.=' AND (g.first_name LIKE ? OR g.last_name LIKE ? OR g.phone LIKE ? OR c.first_name LIKE ? OR c.last_name LIKE ?)';$params=array_merge($params,["%$q%","%$q%","%$q%","%$q%","%$q%"]);}$count=$db->prepare("SELECT COUNT(DISTINCT g.id) FROM guardians g JOIN families f ON f.id=g.family_id LEFT JOIN child_guardians cg ON cg.guardian_id=g.id LEFT JOIN children c ON c.id=cg.child_id$filter");$count->execute($params);$total=(int)$count->fetchColumn();$sql="SELECT g.id,g.family_id AS familyId,g.first_name AS firstName,g.last_name AS lastName,g.phone AS primaryPhone,g.email,g.relationship,g.is_primary AS primaryGuardian,g.is_authorized AS authorisedPickup,f.surname AS familySurname,COUNT(DISTINCT c.id) AS childrenCount,COALESCE(GROUP_CONCAT(DISTINCT TRIM(CONCAT(c.first_name,' ',c.last_name)) ORDER BY c.first_name SEPARATOR ' · '),'—') AS childrenNames,COALESCE(pickups.names,'No additional authorised pickup') AS authorisedPickupNames FROM guardians g JOIN families f ON f.id=g.family_id LEFT JOIN child_guardians cg ON cg.guardian_id=g.id LEFT JOIN children c ON c.id=cg.child_id LEFT JOIN (SELECT family_id,GROUP_CONCAT(DISTINCT TRIM(CONCAT(first_name,' ',last_name)) ORDER BY first_name SEPARATOR ' · ') AS names FROM authorized_pickups WHERE is_active=1 GROUP BY family_id) pickups ON pickups.family_id=f.id$filter GROUP BY g.id,f.surname,pickups.names ORDER BY g.first_name,g.last_name LIMIT $limit OFFSET $offset";$s=$db->prepare($sql);$s->execute($params);api_ok($s->fetchAll(),200,['page'=>$page,'limit'=>$limit,'total'=>$total,'totalPages'=>max(1,(int)ceil($total/$limit))]); }
function api_guardians_directory(PDO $db): never {
    $actor=api_actor($db,true); [$page,$limit,$offset]=api_page(); $params=[$actor['campus_id']]; $where=['f.campus_id=?'];
    $query=trim((string)($_GET['search']??''));
    if($query!=='') { $where[]='(g.first_name LIKE ? OR g.last_name LIKE ? OR g.phone LIKE ? OR g.secondary_phone LIKE ? OR c.first_name LIKE ? OR c.last_name LIKE ?)'; $needle='%'.$query.'%'; $params=array_merge($params,[$needle,$needle,$needle,$needle,$needle,$needle]); }
    if(($relationship=trim((string)($_GET['relationship']??'')))!=='') { $aliases=['Guardian'=>['Guardian','Parent / Guardian','Parent/Guardian']]; $values=$aliases[$relationship]??[$relationship]; $where[]='g.relationship IN ('.implode(',',array_fill(0,count($values),'?')).')'; $params=array_merge($params,$values); }
    if(($profile=trim((string)($_GET['profile']??'')))==='complete') $where[]="g.first_name<>'' AND g.last_name<>'' AND g.phone<>'' AND g.relationship<>'' AND COALESCE(f.home_address,'')<>''";
    if($profile==='needs_info') $where[]="(g.first_name='' OR g.last_name='' OR g.phone='' OR g.relationship='' OR COALESCE(f.home_address,'')='')";
    if(isset($_GET['active']) && $_GET['active']!=='') { $where[]='f.is_active=?'; $params[]=$_GET['active']==='1'?1:0; }
    if(($children=(int)($_GET['childrenCount']??0))>0) { $where[]='(SELECT COUNT(*) FROM child_guardians fcg WHERE fcg.guardian_id=g.id)>=?'; $params[]=$children; }
    if(($_GET['hasAdditionalPickup']??'')==='1') $where[]='EXISTS (SELECT 1 FROM authorized_pickups ap WHERE ap.family_id=f.id AND ap.is_active=1)';
    $filter=' WHERE '.implode(' AND ',$where); $sortMap=['name'=>'g.first_name','relationship'=>'g.relationship','children'=>'childrenCount','joined'=>'f.created_at']; $sort=$sortMap[$_GET['sort']??'name']??'g.first_name'; $order=strtolower((string)($_GET['order']??'asc'))==='desc'?'DESC':'ASC';
    $count=$db->prepare("SELECT COUNT(DISTINCT g.id) FROM guardians g JOIN families f ON f.id=g.family_id LEFT JOIN child_guardians cg ON cg.guardian_id=g.id LEFT JOIN children c ON c.id=cg.child_id$filter"); $count->execute($params); $total=(int)$count->fetchColumn();
    $sql="SELECT g.id,g.family_id AS familyId,g.first_name AS firstName,g.last_name AS lastName,g.phone AS primaryPhone,g.secondary_phone AS secondaryPhone,g.email,g.relationship,g.is_primary AS primaryGuardian,g.is_authorized AS authorisedPickup,f.surname AS familySurname,f.is_active AS active,f.home_address AS homeAddress,f.created_at AS joinedAt,COUNT(DISTINCT c.id) AS childrenCount,COALESCE(GROUP_CONCAT(DISTINCT TRIM(CONCAT(c.first_name,' ',c.last_name)) ORDER BY c.first_name SEPARATOR ' | '),'') AS childrenNames,COALESCE((SELECT COUNT(*) FROM authorized_pickups ap WHERE ap.family_id=f.id AND ap.is_active=1),0) AS additionalPickupCount FROM guardians g JOIN families f ON f.id=g.family_id LEFT JOIN child_guardians cg ON cg.guardian_id=g.id LEFT JOIN children c ON c.id=cg.child_id$filter GROUP BY g.id,f.id ORDER BY $sort $order,g.last_name LIMIT $limit OFFSET $offset";
    $rows=$db->prepare($sql); $rows->execute($params); $records=$rows->fetchAll();
    api_ok($records,200,['page'=>$page,'limit'=>$limit,'total'=>$total,'totalPages'=>max(1,(int)ceil($total/$limit))]);
}
