function api_families_directory(PDO $db): never { $actor=api_actor($db);[$page,$limit,$offset]=api_page();$q=trim((string)($_GET['search']??''));$where=['f.campus_id=?'];$params=[$actor['campus_id']];if($q!==''){$where[]='(f.surname LIKE ? OR f.phone LIKE ? OR g.first_name LIKE ? OR g.last_name LIKE ? OR g.phone LIKE ? OR c.first_name LIKE ? OR c.last_name LIKE ?)';$params=array_merge($params,array_fill(0,7,"%$q%"));}if(($_GET['profile']??'')==='complete')$where[]="EXISTS(SELECT 1 FROM guardians pg WHERE pg.family_id=f.id AND pg.is_primary=1 AND pg.phone<>'' ) AND COALESCE(f.home_address,'')<>''";if(($_GET['profile']??'')==='needs_info')$where[]="(NOT EXISTS(SELECT 1 FROM guardians pg WHERE pg.family_id=f.id AND pg.is_primary=1 AND pg.phone<>'' ) OR COALESCE(f.home_address,'')='')";if(isset($_GET['active'])&&$_GET['active']!==''){$where[]='f.is_active=?';$params[]=(int)$_GET['active'];}$size=(string)($_GET['size']??'');if($size==='1')$where[]='(SELECT COUNT(*) FROM children fc WHERE fc.family_id=f.id AND fc.is_active=1)=1';if($size==='2')$where[]='(SELECT COUNT(*) FROM children fc WHERE fc.family_id=f.id AND fc.is_active=1)=2';if($size==='3')$where[]='(SELECT COUNT(*) FROM children fc WHERE fc.family_id=f.id AND fc.is_active=1)>=3';if(($_GET['multipleGuardians']??'')==='1')$where[]='(SELECT COUNT(*) FROM guardians fg WHERE fg.family_id=f.id)>=2';$filter=' WHERE '.implode(' AND ',$where);$count=$db->prepare("SELECT COUNT(DISTINCT f.id) FROM families f LEFT JOIN guardians g ON g.family_id=f.id LEFT JOIN children c ON c.family_id=f.id$filter");$count->execute($params);$total=(int)$count->fetchColumn();$order=strtolower((string)($_GET['order']??'asc'))==='desc'?'DESC':'ASC';$sql="SELECT f.id,f.surname AS familyName,f.family_code AS familyCode,f.phone,f.email,f.home_address AS homeAddress,f.notes,f.is_active AS active,f.created_at AS joinedAt,COUNT(DISTINCT c.id) AS childrenCount,COUNT(DISTINCT g.id) AS guardiansCount,COALESCE(GROUP_CONCAT(DISTINCT CONCAT(c.id,':',c.first_name,' ',c.last_name) ORDER BY c.first_name SEPARATOR ' | '),'') AS children,COALESCE(GROUP_CONCAT(DISTINCT CONCAT(g.id,':',g.first_name,' ',g.last_name) ORDER BY g.is_primary DESC,g.first_name SEPARATOR ' | '),'') AS guardians,COALESCE(MAX(CASE WHEN g.is_primary=1 THEN g.phone END),f.phone) AS primaryPhone,COALESCE(MAX(CASE WHEN g.is_primary=1 THEN CONCAT(g.first_name,' ',g.last_name) END),'') AS primaryGuardianName,(SELECT COUNT(*) FROM authorized_pickups ap WHERE ap.family_id=f.id AND ap.is_active=1) AS additionalPickupPeopleCount FROM families f LEFT JOIN guardians g ON g.family_id=f.id LEFT JOIN children c ON c.family_id=f.id AND c.is_active=1$filter GROUP BY f.id ORDER BY f.surname $order LIMIT $limit OFFSET $offset";$s=$db->prepare($sql);$s->execute($params);$rows=$s->fetchAll();foreach($rows as &$row)$row['profileStatus']=($row['primaryGuardianName']!==''&&$row['primaryPhone']!==''&&trim((string)$row['homeAddress'])!=='')?'COMPLETE':'NEEDS_INFO';unset($row);api_ok($rows,200,['page'=>$page,'limit'=>$limit,'total'=>$total,'totalPages'=>max(1,(int)ceil($total/$limit))]); }
