function api_prepare_sunday(PDO $db): never {
    $actor=api_actor($db,true);$v=api_input();$timezone=new DateTimeZone('Africa/Lagos');$today=new DateTimeImmutable('today',$timezone);$date=trim((string)($v['serviceDate']??''));
    if($date===''){ $days=(7-(int)$today->format('w'))%7; $serviceDate=$today->modify("+{$days} days"); }
    else {$serviceDate=DateTimeImmutable::createFromFormat('!Y-m-d',$date,$timezone);$errors=DateTimeImmutable::getLastErrors();if(!$serviceDate||($errors!==false&&($errors['warning_count']||$errors['error_count']))||$serviceDate->format('Y-m-d')!==$date)api_error('VALIDATION_ERROR','Choose a valid Sunday date.',422);}
    if($serviceDate->format('w')!=='0')api_error('VALIDATION_ERROR','Service preparation is available for Sundays only.',422);
    $specifications=[['First Service','FIRST_SERVICE',1,'08:30:00','10:15:00'],['Second Service','SECOND_SERVICE',2,'10:30:00','12:15:00']];$prepared=[];
    $db->beginTransaction();try{foreach($specifications as [$name,$type,$order,$start,$end]){$existing=$db->prepare('SELECT id FROM service_sessions WHERE campus_id=? AND service_date=? AND service_type=? LIMIT 1');$existing->execute([$actor['campus_id'],$serviceDate->format('Y-m-d'),$type]);$id=(int)$existing->fetchColumn();if(!$id){$insert=$db->prepare('INSERT INTO service_sessions(campus_id,name,starts_at,ends_at,is_open,service_date,service_order,service_type) VALUES(?,?,?,?,0,?,?,?)');$insert->execute([$actor['campus_id'],$name,$serviceDate->format('Y-m-d').' '.$start,$serviceDate->format('Y-m-d').' '.$end,$serviceDate->format('Y-m-d'),$order,$type]);$id=(int)$db->lastInsertId();api_audit($db,$actor,'SERVICE_SESSION_PREPARED','ServiceSession',$id,['serviceType'=>$type,'serviceDate'=>$serviceDate->format('Y-m-d')]);}$prepared[]=['id'=>$id,'name'=>$name,'serviceDate'=>$serviceDate->format('Y-m-d'),'serviceType'=>$type];}$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}
    api_ok(['serviceDate'=>$serviceDate->format('Y-m-d'),'sessions'=>$prepared],201);
}
function api_system_status(PDO $db): never {
    $actor=api_actor($db);
    $campus=$db->prepare('SELECT id,name,code,timezone FROM campuses WHERE id=?');$campus->execute([$actor['campus_id']]);
    $session=$db->prepare('SELECT id,name,service_date AS serviceDate,service_type AS serviceType,starts_at AS startsAt FROM service_sessions WHERE campus_id=? AND is_open=1 AND service_date=CURDATE() ORDER BY starts_at DESC LIMIT 1');$session->execute([$actor['campus_id']]);
    api_ok(['connected'=>true,'checkedAt'=>(new DateTimeImmutable('now',new DateTimeZone('Africa/Lagos')))->format(DATE_ATOM),'campus'=>$campus->fetch()?:null,'serviceSession'=>$session->fetch()?:null,'accessLevel'=>$actor['access_level'],'teamStatus'=>$actor['team_status']]);
}
function api_roster(PDO $db): never { $actor=api_actor($db,true);$where=['1=1'];$params=[];foreach(['userId'=>'ra.user_id','dutyTypeId'=>'ra.duty_type_id','classId'=>'ra.class_id','serviceSessionId'=>'ra.service_session_id'] as $key=>$col)if(isset($_GET[$key])){$where[]="$col=?";$params[]=(int)$_GET[$key];}if(isset($_GET['month'])){$where[]='MONTH(ra.assignment_date)=?';$params[]=(int)$_GET['month'];}if(isset($_GET['year'])){$where[]='YEAR(ra.assignment_date)=?';$params[]=(int)$_GET['year'];}$s=$db->prepare('SELECT ra.id,ra.user_id AS userId,ra.assignment_date AS assignmentDate,ra.service_session_id AS serviceSessionId,ra.class_id AS classId,ra.status,ra.confirmed_at AS confirmedAt,dt.name AS dutyName,dt.code AS dutyCode,c.name AS className,u.name AS teacherName FROM roster_assignments ra JOIN staff_users u ON u.id=ra.user_id JOIN teacher_profiles p ON p.staff_user_id=u.id JOIN duty_types dt ON dt.id=ra.duty_type_id LEFT JOIN classes c ON c.id=ra.class_id WHERE '.implode(' AND ',$where).' ORDER BY ra.assignment_date,ra.id');$s->execute($params);api_ok($s->fetchAll()); }
function api_roster_month_bounds(): array {
    $zone=new DateTimeZone('Africa/Lagos');$today=new DateTimeImmutable('today',$zone);$year=(int)($_GET['year']??$today->format('Y'));$month=(int)($_GET['month']??$today->format('n'));
    if($year<2020||$year>2100||$month<1||$month>12)api_error('VALIDATION_ERROR','Choose a valid roster month.',422);
    $from=new DateTimeImmutable(sprintf('%04d-%02d-01',$year,$month),$zone);return[$from,$from->modify('+1 month')];
}
function api_roster_month_locked(string $date): bool {
    $zone=new DateTimeZone('Africa/Lagos');
    try {$target=new DateTimeImmutable($date,$zone);} catch(Throwable $e) {return false;}
    return $target->format('Y-m')<(new DateTimeImmutable('first day of this month',$zone))->format('Y-m');
}
function api_roster_sundays(DateTimeImmutable $from,DateTimeImmutable $until): array {$days=[];$day=$from->modify('first sunday');while($day<$until){$days[]=$day->format('Y-m-d');$day=$day->modify('+7 days');}return $days;}
function api_roster_management(PDO $db): never {
    $actor=api_actor($db);[$from,$until]=api_roster_month_bounds();$sundays=api_roster_sundays($from,$until);
    $teachers=$db->prepare("SELECT s.id,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,''),' ',COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))),''),s.name) AS name,s.access_level AS accessLevel,COALESCE(op.onboarding_status,CASE WHEN s.team_status='PROBATION' THEN 'PROBATION' ELSE 'ONBOARDED' END) AS onboardingStatus,COALESCE(op.probation_started_at,DATE(s.joined_at)) AS probationStartedAt,COALESCE(op.probation_target_weeks,4) AS probationTargetWeeks,p.profile_image_url AS profileImageUrl,p.whatsapp_number AS whatsappNumber,p.mobile_number AS mobileNumber FROM staff_users s JOIN teacher_profiles p ON p.staff_user_id=s.id LEFT JOIN staff_onboarding_profiles op ON op.staff_user_id=s.id WHERE s.campus_id=? AND s.account_status='VERIFIED' AND s.is_active=1 AND s.team_status<>'INACTIVE' ORDER BY p.first_name,p.last_name,s.name");$teachers->execute([$actor['campus_id']]);
    $teacherRows=$teachers->fetchAll();foreach($teacherRows as &$teacherRow)$teacherRow['teamStatus']=$teacherRow['onboardingStatus'];unset($teacherRow);$duties=$db->query("SELECT id,name,code,category,requires_class AS requiresClass FROM duty_types WHERE active=1 ORDER BY FIELD(category,'FIRST_SERVICE','SECOND_SERVICE','NON_TEACHING'),FIELD(code,'HEAD_OF_SERVICE','ASSISTANT_HEAD_OF_SERVICE_1','ASSISTANT_HEAD_OF_SERVICE_2') DESC,name")->fetchAll();
    $sessions=$db->prepare("SELECT id,name,service_date AS serviceDate,service_type AS serviceType,is_open AS isOpen FROM service_sessions WHERE campus_id=? AND service_date>=? AND service_date<? ORDER BY service_date,starts_at");$sessions->execute([$actor['campus_id'],$from->format('Y-m-d'),$until->format('Y-m-d')]);
    $classes=$db->prepare('SELECT id,name FROM classes WHERE campus_id=? AND is_active=1 ORDER BY display_order,name');$classes->execute([$actor['campus_id']]);
    $assignments=$db->prepare("SELECT ra.id,ra.user_id AS userId,ra.assignment_date AS assignmentDate,ra.service_session_id AS serviceSessionId,ra.class_id AS classId,ra.status,CASE WHEN dt.code='ATTENDANCE' THEN 'Attendance' ELSE dt.name END AS dutyName,dt.code AS dutyCode,dt.category AS dutyCategory,c.name AS className,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,''),' ',COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))),''),u.name) AS teacherName,u.access_level AS accessLevel,COALESCE(op.onboarding_status,CASE WHEN u.team_status='PROBATION' THEN 'PROBATION' ELSE 'ONBOARDED' END) AS onboardingStatus,COALESCE(op.probation_started_at,DATE(u.joined_at)) AS probationStartedAt,COALESCE(op.probation_target_weeks,4) AS probationTargetWeeks,p.profile_image_url AS profileImageUrl,p.whatsapp_number AS whatsappNumber,p.mobile_number AS mobileNumber,ss.name AS serviceName,ss.service_type AS serviceType FROM roster_assignments ra JOIN staff_users u ON u.id=ra.user_id JOIN teacher_profiles p ON p.staff_user_id=u.id LEFT JOIN staff_onboarding_profiles op ON op.staff_user_id=u.id JOIN duty_types dt ON dt.id=ra.duty_type_id LEFT JOIN classes c ON c.id=ra.class_id LEFT JOIN service_sessions ss ON ss.id=ra.service_session_id WHERE u.campus_id=? AND ra.assignment_date>=? AND ra.assignment_date<? AND ra.status NOT IN ('CANCELLED','REPLACED') ORDER BY ra.assignment_date,ss.starts_at,dt.name,u.name");$assignments->execute([$actor['campus_id'],$from->format('Y-m-d'),$until->format('Y-m-d')]);$assignmentRows=$assignments->fetchAll();foreach($assignmentRows as &$assignmentRow)$assignmentRow['teamStatus']=$assignmentRow['onboardingStatus'];unset($assignmentRow);
    $state=$db->prepare('SELECT status,published_at AS publishedAt FROM roster_month_states WHERE campus_id=? AND roster_month=? LIMIT 1');$state->execute([$actor['campus_id'],$from->format('Y-m-d')]);$state=$state->fetch()?:['status'=>'DRAFT','publishedAt'=>null];
    $required=0;$filled=0;foreach($sundays as $date){foreach(['FIRST_SERVICE_TEAM','CLASS_TEACHER:Tribe A','CLASS_TEACHER:Tribe B','CLASS_TEACHER:Tribe C','TEACHER_AT_DOOR','ASSEMBLY','ATTENDANCE','HEAD_OF_SERVICE','ASSISTANT_HEAD_OF_SERVICE_1','ASSISTANT_HEAD_OF_SERVICE_2'] as $slot){$required++;foreach($assignmentRows as $row){$matches=$row['assignmentDate']===$date&&($slot===$row['dutyCode']||($row['dutyCode']==='CLASS_TEACHER'&&$slot==='CLASS_TEACHER:'.($row['className']??'')));if($matches){$filled++;break;}}}}
    api_ok(['month'=>$from->format('Y-m'),'sundays'=>$sundays,'state'=>$state,'permissions'=>['isSuperAdmin'=>$actor['access_level']==='TPK_SUPER_ADMIN','locked'=>api_roster_month_locked($from->format('Y-m-d'))],'teachers'=>$teacherRows,'duties'=>$duties,'sessions'=>$sessions->fetchAll(),'classes'=>$classes->fetchAll(),'assignments'=>$assignmentRows,'summary'=>['sundays'=>count($sundays),'teamMembers'=>count($teacherRows),'assignments'=>count($assignmentRows),'unfilled'=>max(0,$required-$filled)]]);
}
function api_roster_session(PDO $db,array $actor,string $date,string $type): int {
    $existing=$db->prepare('SELECT id FROM service_sessions WHERE campus_id=? AND service_date=? AND service_type=? LIMIT 1');$existing->execute([$actor['campus_id'],$date,$type]);if($id=(int)$existing->fetchColumn())return $id;
    $spec=$type==='FIRST_SERVICE'?['First Service',1,'08:30:00','10:15:00']:['Second Service',2,'10:30:00','12:15:00'];$insert=$db->prepare('INSERT INTO service_sessions(campus_id,name,starts_at,ends_at,is_open,service_date,service_order,service_type) VALUES(?,?,?,?,0,?,?,?)');$insert->execute([$actor['campus_id'],$spec[0],$date.' '.$spec[2],$date.' '.$spec[3],$date,$spec[1],$type]);return(int)$db->lastInsertId();
}
function api_create_roster_assignment(PDO $db): never {
    $actor=api_actor($db,true);$v=api_input();$ids=array_values(array_unique(array_filter(array_map('intval',is_array($v['userIds']??null)?$v['userIds']:[($v['userId']??0)]))));$dutyTypeId=(int)($v['dutyTypeId']??0);$classId=(int)($v['classId']??0);$date=trim((string)($v['assignmentDate']??''));$sessionId=(int)($v['serviceSessionId']??0);$replaceId=(int)($v['replaceAssignmentId']??0);
    if(!$ids||!$dutyTypeId)api_error('VALIDATION_ERROR','Choose at least one teacher and a duty.',422);$duty=$db->prepare('SELECT id,name,code,category,requires_class FROM duty_types WHERE id=? AND active=1');$duty->execute([$dutyTypeId]);$duty=$duty->fetch();if(!$duty)api_error('DUTY_NOT_FOUND','Choose an active duty.',422);
    if(!$date&&$sessionId){$sessionDate=$db->prepare('SELECT service_date FROM service_sessions WHERE id=? AND campus_id=?');$sessionDate->execute([$sessionId,$actor['campus_id']]);$date=(string)$sessionDate->fetchColumn();}if(!$date||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))api_error('VALIDATION_ERROR','Choose an assignment date.',422);if(api_roster_month_locked($date))api_error('ROSTER_MONTH_LOCKED','This roster month has ended. Assignments are read-only.',409);
    if($duty['category']!=='NON_TEACHING'){$serviceType=(string)($v['serviceType']??'');if(!$serviceType){$serviceType=$duty['category']==='FIRST_SERVICE'?'FIRST_SERVICE':'SECOND_SERVICE';}if(!in_array($serviceType,['FIRST_SERVICE','SECOND_SERVICE'],true))api_error('VALIDATION_ERROR','Choose First Service or Second Service.',422);if((new DateTimeImmutable($date))->format('w')!=='0')api_error('VALIDATION_ERROR','Sunday duties must be assigned to a Sunday.');$sessionId=$sessionId?:api_roster_session($db,$actor,$date,$serviceType);}else{if(!in_array((new DateTimeImmutable($date))->format('w'),['4','6'],true))api_error('VALIDATION_ERROR','Non-teaching duties can only be assigned on Thursdays or Saturdays.',422);$sessionId=0;}
    if((bool)$duty['requires_class']&&!$classId)api_error('CLASS_REQUIRED','Choose a class for this teaching duty.',422);if($classId){$class=$db->prepare('SELECT id FROM classes WHERE id=? AND campus_id=? AND is_active=1');$class->execute([$classId,$actor['campus_id']]);if(!$class->fetch())api_error('CLASS_NOT_FOUND','Choose an active Petra Wuse class.',422);}
    $serviceLeadership=['HEAD_OF_SERVICE','ASSISTANT_HEAD_OF_SERVICE_1','ASSISTANT_HEAD_OF_SERVICE_2'];if(in_array($duty['code'],$serviceLeadership,true)&&count($ids)>1)api_error('VALIDATION_ERROR','Only one teacher can hold each service-leadership role.',422);if(in_array($duty['code'],$serviceLeadership,true)){$head=$db->prepare("SELECT ra.id FROM roster_assignments ra JOIN duty_types dt ON dt.id=ra.duty_type_id WHERE ra.service_session_id=? AND dt.code=? AND ra.status NOT IN ('CANCELLED','REPLACED','ABSENT') LIMIT 1");$head->execute([$sessionId,$duty['code']]);$existingHead=(int)$head->fetchColumn();if($existingHead&&$existingHead!==$replaceId)api_error('SERVICE_LEADERSHIP_ALREADY_ASSIGNED','This service-leadership role is already assigned.',409);}
    $created=[];$db->beginTransaction();try{foreach($ids as $userId){$teacher=$db->prepare("SELECT s.id FROM staff_users s JOIN teacher_profiles p ON p.staff_user_id=s.id WHERE s.id=? AND s.campus_id=? AND s.account_status='VERIFIED' AND s.is_active=1 AND s.team_status<>'INACTIVE'");$teacher->execute([$userId,$actor['campus_id']]);if(!$teacher->fetch())api_error('TEACHER_NOT_AVAILABLE','Choose active verified TPK teachers.',422);$duplicate=$db->prepare('SELECT id FROM roster_assignments WHERE user_id=? AND assignment_date=? AND duty_type_id=? AND COALESCE(service_session_id,0)=? AND status NOT IN (\'CANCELLED\',\'REPLACED\') LIMIT 1');$duplicate->execute([$userId,$date,$dutyTypeId,$sessionId]);if($duplicate->fetch())continue;$insert=$db->prepare('INSERT INTO roster_assignments(user_id,assignment_date,service_session_id,duty_type_id,class_id,assigned_by) VALUES(?,?,?,?,?,?)');$insert->execute([$userId,$date,$sessionId?:null,$dutyTypeId,$classId?:null,$actor['id']]);$id=(int)$db->lastInsertId();$created[]=$id;api_audit($db,$actor,'ROSTER_ASSIGNMENT_CREATED','RosterAssignment',$id,['teacherId'=>$userId,'dutyCode'=>$duty['code'],'serviceSessionId'=>$sessionId]);}if($replaceId&&$created){$replace=$db->prepare("UPDATE roster_assignments ra JOIN staff_users s ON s.id=ra.user_id SET ra.status='REPLACED' WHERE ra.id=? AND s.campus_id=? AND ra.status NOT IN ('CANCELLED','REPLACED')");$replace->execute([$replaceId,$actor['campus_id']]);if(!$replace->rowCount())api_error('ASSIGNMENT_NOT_AVAILABLE','The assignment to replace is no longer available.',404);api_audit($db,$actor,'ROSTER_ASSIGNMENT_REPLACED','RosterAssignment',$replaceId,['replacementIds'=>$created]);}$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
    api_ok(['ids'=>$created,'assignmentDate'=>$date,'dutyName'=>$duty['name'],'created'=>count($created)],201);
}
function api_cancel_roster_assignment(PDO $db,int $id): never {$actor=api_actor($db,true);$lookup=$db->prepare('SELECT ra.assignment_date FROM roster_assignments ra JOIN staff_users u ON u.id=ra.user_id WHERE ra.id=? AND u.campus_id=?');$lookup->execute([$id,$actor['campus_id']]);$assignment=$lookup->fetch();if(!$assignment)api_error('ASSIGNMENT_NOT_AVAILABLE','This assignment is no longer available.',404);if(api_roster_month_locked((string)$assignment['assignment_date']))api_error('ROSTER_MONTH_LOCKED','This roster month has ended. Assignments are read-only.',409);$s=$db->prepare('UPDATE roster_assignments SET status=\'CANCELLED\' WHERE id=? AND status NOT IN (\'CANCELLED\',\'REPLACED\')');$s->execute([$id]);if(!$s->rowCount())api_error('ASSIGNMENT_NOT_AVAILABLE','This assignment is no longer available.',404);api_audit($db,$actor,'ROSTER_ASSIGNMENT_CANCELLED','RosterAssignment',$id);api_ok(['id'=>$id,'cancelled'=>true]);}
function api_send_roster_publication_whatsapp(PDO $db,array $actor,string $month,string $date): array {
    $assignments=$db->prepare("SELECT ra.user_id AS userId,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,''),' ',COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))),''),u.name) AS teacherName,COALESCE(NULLIF(p.whatsapp_number,''),NULLIF(p.mobile_number,''),'') AS phone,GROUP_CONCAT(DISTINCT CONCAT(DATE_FORMAT(ra.assignment_date,'%e %b'),' · ',COALESCE(ss.name,'TPK duty'),' · ',dt.name,IF(c.name IS NULL,'',CONCAT(' · ',c.name))) ORDER BY ra.assignment_date,ss.starts_at,dt.name SEPARATOR '; ') AS assignmentSummary FROM roster_assignments ra JOIN staff_users u ON u.id=ra.user_id JOIN duty_types dt ON dt.id=ra.duty_type_id LEFT JOIN teacher_profiles p ON p.staff_user_id=u.id LEFT JOIN service_sessions ss ON ss.id=ra.service_session_id LEFT JOIN classes c ON c.id=ra.class_id WHERE u.campus_id=? AND ra.assignment_date>=? AND ra.assignment_date<DATE_ADD(?,INTERVAL 1 MONTH) AND ra.status NOT IN ('CANCELLED','REPLACED') GROUP BY ra.user_id,u.name,p.title,p.first_name,p.last_name,p.whatsapp_number,p.mobile_number");
    $assignments->execute([(int)$actor['campus_id'],$date,$date]);
    $monthLabel=(new DateTimeImmutable($date))->format('F Y');
    $origin=rtrim((string)(getenv('TPK_FRONTEND_URL') ?: (getenv('FRONTEND_ORIGIN') ?: 'http://localhost:3000')),'/');
    $rosterUrl=$origin.'/account/roster?month='.rawurlencode($month);
    $upsert=$db->prepare("INSERT INTO roster_notification_dispatches(campus_id,staff_user_id,roster_month,status,provider_message) VALUES(?,?,?,'PENDING',NULL) ON DUPLICATE KEY UPDATE status='PENDING',provider_message=NULL,updated_at=CURRENT_TIMESTAMP");
    $mark=$db->prepare('UPDATE roster_notification_dispatches SET status=?,provider_message=? WHERE campus_id=? AND staff_user_id=? AND roster_month=?');
    $sent=0;$failed=0;
    foreach($assignments->fetchAll() as $teacher){
        $userId=(int)$teacher['userId'];$upsert->execute([(int)$actor['campus_id'],$userId,$date]);
        $phone=tpk_normalize_nigerian_phone((string)$teacher['phone']);
        if(!$phone){$failed++;$mark->execute(['FAILED','No verified WhatsApp or mobile number is available.',(int)$actor['campus_id'],$userId,$date]);continue;}
        $summary=trim((string)$teacher['assignmentSummary']);if(strlen($summary)>900)$summary=substr($summary,0,897).'...';
        try{
            $providerMessage=tpk_send_roster_whatsapp($phone,(string)$teacher['teacherName'],$monthLabel,$summary,$rosterUrl);
            $sent++;$mark->execute(['SENT',substr($providerMessage,0,500),(int)$actor['campus_id'],$userId,$date]);
        }catch(Throwable $error){
            $failed++;$mark->execute(['FAILED',substr($error->getMessage(),0,500),(int)$actor['campus_id'],$userId,$date]);
        }
    }
    return ['teachers'=>$sent+$failed,'sent'=>$sent,'failed'=>$failed];
}

function api_roster_month_state(PDO $db): never {
    $actor=api_actor($db,true);$v=api_input();$month=trim((string)($v['month']??''));$status=(string)($v['status']??'DRAFT');
    if(!preg_match('/^\d{4}-\d{2}$/',$month)||!in_array($status,['DRAFT','PUBLISHED'],true))api_error('VALIDATION_ERROR','Choose a valid roster month and state.',422);
    $date=$month.'-01';if(api_roster_month_locked($date))api_error('ROSTER_MONTH_LOCKED','This roster month has ended. Assignments are read-only.',409);
    $previous=$db->prepare('SELECT status FROM roster_month_states WHERE campus_id=? AND roster_month=?');$previous->execute([(int)$actor['campus_id'],$date]);$wasPublished=$previous->fetchColumn()==='PUBLISHED';
    $db->prepare('INSERT INTO roster_month_states(campus_id,roster_month,status,published_at,published_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),published_at=VALUES(published_at),published_by=VALUES(published_by)')->execute([(int)$actor['campus_id'],$date,$status,$status==='PUBLISHED'?date('Y-m-d H:i:s'):null,$status==='PUBLISHED'?(int)$actor['id']:null]);
    $notifications=['teachers'=>0,'sent'=>0,'failed'=>0];
    if($status==='PUBLISHED'&&!$wasPublished)$notifications=api_send_roster_publication_whatsapp($db,$actor,$month,$date);
    api_audit($db,$actor,'ROSTER_MONTH_'.$status,'RosterMonth',0,['month'=>$month,'teachers'=>$notifications['teachers'],'whatsappSent'=>$notifications['sent'],'whatsappFailed'=>$notifications['failed']]);
    api_ok(['month'=>$month,'status'=>$status,'teachers'=>$notifications['teachers'],'notificationsSent'=>$notifications['sent'],'notificationsFailed'=>$notifications['failed'],'notificationsSkipped'=>$status==='PUBLISHED'&&$wasPublished]);
}
function api_my_roster(PDO $db,string $scope): never { $actor=api_actor($db);$date=$scope==='today'?' AND ra.assignment_date=CURDATE()':($scope==='upcoming'?' AND ra.assignment_date>=CURDATE()':'');$s=$db->prepare("SELECT ra.id,ra.assignment_date AS assignmentDate,ra.service_session_id AS serviceSessionId,ra.status,ra.confirmed_at AS confirmedAt,dt.name AS dutyName,dt.code AS dutyCode,c.name AS className FROM roster_assignments ra JOIN duty_types dt ON dt.id=ra.duty_type_id LEFT JOIN classes c ON c.id=ra.class_id WHERE ra.user_id=?$date ORDER BY ra.assignment_date,ra.id");$s->execute([$actor['id']]);api_ok($s->fetchAll()); }
function api_confirm_presence(PDO $db,int $id): never { $actor=api_actor($db);$s=$db->prepare("UPDATE roster_assignments SET status='PRESENT',confirmed_at=NOW() WHERE id=? AND user_id=? AND status='ASSIGNED'");$s->execute([$id,$actor['id']]);if(!$s->rowCount())api_error('ASSIGNMENT_NOT_AVAILABLE','This assignment cannot be confirmed.',409);api_audit($db,$actor,'ROSTER_PRESENCE_CONFIRMED','RosterAssignment',$id);api_ok(['assignmentId'=>$id,'status'=>'PRESENT']); }
function api_dashboard(PDO $db): never {
    $actor=api_actor($db);$allowed=null;/* Every teacher sees the four-class attendance summary; child records remain permission-scoped elsewhere. */$where=['c.campus_id=?','c.is_active=1'];$params=[$actor['campus_id']];
    if($allowed!==null){if(!$allowed) $where[]='1=0'; else {$where[]='c.id IN ('.implode(',',array_fill(0,count($allowed),'?')).')';$params=array_merge($params,$allowed);}}
    $requestedSessionId=(int)($_GET['serviceSessionId']??0);$session=$db->prepare('SELECT id,name,service_type AS serviceType,service_date AS serviceDate FROM service_sessions WHERE campus_id=? AND id=? LIMIT 1');if($requestedSessionId){$session->execute([$actor['campus_id'],$requestedSessionId]);$activeSession=$session->fetch();if(!$activeSession)api_error('SERVICE_SESSION_NOT_FOUND','That service session is not available for this campus.',404);}else{$session=$db->prepare('SELECT id,name,service_type AS serviceType,service_date AS serviceDate FROM service_sessions WHERE campus_id=? AND is_open=1 AND service_date=CURDATE() ORDER BY starts_at DESC LIMIT 1');$session->execute([$actor['campus_id']]);$activeSession=$session->fetch();}$sessionId=(int)($activeSession['id']??0);
    $classes=$db->prepare('SELECT c.id,c.name,c.age_label AS ageLabel,COUNT(ch.id) AS total FROM classes c LEFT JOIN children ch ON ch.class_id=c.id AND ch.is_active=1 WHERE '.implode(' AND ',$where).' GROUP BY c.id,c.name,c.age_label ORDER BY c.display_order,c.name');$classes->execute($params);$rows=$classes->fetchAll();$checked=0;$picked=0;
    foreach($rows as &$row){$row['total']=(int)$row['total'];$row['checkedIn']=0;if($sessionId){$a=$db->prepare("SELECT status,COUNT(*) AS amount FROM attendance WHERE service_session_id=? AND class_id=? GROUP BY status");$a->execute([$sessionId,$row['id']]);foreach($a->fetchAll() as $state){$row['checkedIn']+=(int)$state['amount'];$checked+=(int)$state['amount'];if($state['status']==='PICKED_UP')$picked+=(int)$state['amount'];}}}unset($row);
    $personal=$db->prepare("SELECT ra.id,ra.assignment_date AS assignmentDate,dt.name AS dutyName,c.name AS className,ss.name AS serviceName FROM roster_assignments ra JOIN duty_types dt ON dt.id=ra.duty_type_id LEFT JOIN classes c ON c.id=ra.class_id LEFT JOIN service_sessions ss ON ss.id=ra.service_session_id WHERE ra.user_id=? AND ra.status NOT IN ('CANCELLED','REPLACED') AND ra.assignment_date>=CURDATE() ORDER BY ra.assignment_date,ra.id LIMIT 1");$personal->execute([$actor['id']]);$personalAssignment=$personal->fetch()?:null;
    $todayTeam=[];$upcoming=[];$needs=[];$relations=['total'=>0,'contacted'=>0,'pending'=>0];
    if($actor['access_level']==='TPK_SUPER_ADMIN'){
        $team=$db->prepare("SELECT ra.id AS assignmentId,ra.user_id AS userId,COALESCE(ss.service_type,'UNSCHEDULED') AS serviceType,ra.status,dt.name AS dutyName,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,''),' ',COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))),''),u.name) AS teacherName,p.profile_image_url AS profileImageUrl FROM roster_assignments ra JOIN staff_users u ON u.id=ra.user_id JOIN duty_types dt ON dt.id=ra.duty_type_id LEFT JOIN teacher_profiles p ON p.staff_user_id=u.id LEFT JOIN service_sessions ss ON ss.id=ra.service_session_id WHERE ra.assignment_date=COALESCE((SELECT service_date FROM service_sessions WHERE id=?),CURDATE()) AND ra.status NOT IN ('CANCELLED','REPLACED') ORDER BY COALESCE(ss.service_type,'UNSCHEDULED'),dt.name,u.name");$team->execute([$sessionId?:null]);$todayTeam=$team->fetchAll();
        $up=$db->prepare("SELECT assignment_date AS assignmentDate,COALESCE(service_session_id,0) AS serviceSessionId,COUNT(*) AS duties,SUM(status NOT IN ('CANCELLED','REPLACED')) AS filled FROM roster_assignments WHERE assignment_date>=CURDATE() AND status NOT IN ('CANCELLED','REPLACED') GROUP BY assignment_date,service_session_id ORDER BY assignment_date LIMIT 2");$up->execute();$upcoming=$up->fetchAll();
        $need=$db->prepare("SELECT 'UNPICKED_UP' AS type,'URGENT' AS severity,CONCAT(COUNT(*),' children are still awaiting pickup') AS message,'Review Pick-Up' AS actionLabel,'/account/pick-up' AS actionDestination FROM attendance WHERE service_session_id=? AND status='CHECKED_IN' HAVING COUNT(*)>0");
        if($sessionId){try{$need->execute([$sessionId]);$needs=$need->fetchAll();}catch(Throwable $e){$needs=[];}}
        $task=$db->prepare("SELECT COUNT(*) AS total,SUM(status='RESOLVED') AS contacted,SUM(status IN ('OPEN','IN_PROGRESS')) AS pending FROM follow_up_tasks WHERE campus_id=?");try{$task->execute([$actor['campus_id']]);$relations=$task->fetch()?:$relations;}catch(Throwable $e){}
        $classNeed=$db->prepare("SELECT COUNT(*) FROM children c JOIN families f ON f.id=c.family_id WHERE f.campus_id=? AND c.class_assignment_required=1 AND c.is_active=1");$classNeed->execute([$actor['campus_id']]);$amount=(int)$classNeed->fetchColumn();if($amount)$needs[]=['type'=>'NEEDS_CLASS_ASSIGNMENT','severity'=>'HIGH','message'=>"{$amount} children need a class assignment",'actionLabel'=>'Assign Class','actionDestination'=>'/account/children'];
    }
    if($actor['access_level']!=='TPK_SUPER_ADMIN'){$team=$db->prepare("SELECT ra.id AS assignmentId,ra.user_id AS userId,COALESCE(ss.service_type,'UNSCHEDULED') AS serviceType,ra.status,dt.name AS dutyName,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,''),' ',COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))),''),u.name) AS teacherName,p.profile_image_url AS profileImageUrl FROM roster_assignments ra JOIN staff_users u ON u.id=ra.user_id JOIN duty_types dt ON dt.id=ra.duty_type_id LEFT JOIN teacher_profiles p ON p.staff_user_id=u.id LEFT JOIN service_sessions ss ON ss.id=ra.service_session_id WHERE ra.assignment_date=COALESCE((SELECT service_date FROM service_sessions WHERE id=?),CURDATE()) AND ra.status NOT IN ('CANCELLED','REPLACED') ORDER BY COALESCE(ss.service_type,'UNSCHEDULED'),dt.name,u.name");$team->execute([$sessionId?:null]);$todayTeam=$team->fetchAll();}
    $allClasses=$db->prepare('SELECT COUNT(*) FROM classes WHERE campus_id=? AND is_active=1');$allClasses->execute([$actor['campus_id']]);
    api_ok(['serviceSession'=>$activeSession?:null,'serviceSessionId'=>$sessionId?:null,'metrics'=>['checkedIn'=>$checked,'pickedUp'=>$picked,'stillPresent'=>$checked-$picked,'activeClasses'=>(int)$allClasses->fetchColumn()],'classes'=>$rows,'personalAssignment'=>$personalAssignment,'todayTeam'=>$todayTeam,'needsAttention'=>$needs,'childrenRelations'=>$relations,'upcomingRoster'=>$upcoming]);
}
function api_notifications(PDO $db): never {
    $actor=api_actor($db); $campus=(int)$actor['campus_id']; $isSuper=$actor['access_level']==='TPK_SUPER_ADMIN'; $followUpLead=api_is_followup_lead($actor);
    $allowed=api_permitted_class_ids($db,$actor); $items=[];
    $sessionId=(int)($_GET['serviceSessionId']??0);
    if($sessionId){$session=$db->prepare('SELECT id,name,service_date AS serviceDate FROM service_sessions WHERE id=? AND campus_id=?');$session->execute([$sessionId,$campus]);$service=$session->fetch();if(!$service)api_error('SERVICE_SESSION_NOT_FOUND','That service session is not available for this campus.',404);}
    else {$session=$db->prepare("SELECT id,name,service_date AS serviceDate FROM service_sessions WHERE campus_id=? AND service_type IN ('FIRST_SERVICE','SECOND_SERVICE') ORDER BY service_date DESC,starts_at DESC LIMIT 1");$session->execute([$campus]);$service=$session->fetch()?:null;$sessionId=(int)($service['id']??0);}
    if($sessionId&&$service){$where=['a.service_session_id=?','a.status IN (\'CHECKED_IN\',\'PICKUP_REQUESTED\')'];$params=[$sessionId];if($allowed!==null){if(!$allowed)$where[]='1=0';else{$where[]='a.class_id IN ('.implode(',',array_fill(0,count($allowed),'?')).')';$params=array_merge($params,$allowed);}}$still=$db->prepare('SELECT COUNT(*) FROM attendance a WHERE '.implode(' AND ',$where));$still->execute($params);$count=(int)$still->fetchColumn();if($count)$items[]=['id'=>"pickup-{$sessionId}-{$count}",'kind'=>'PICKUP','severity'=>'URGENT','title'=>"{$count} child".($count===1?' is':'ren are').' still awaiting pickup','detail'=>($service['name']??'Selected service').' · Safeguarding release is still outstanding','href'=>'/account/pick-up'];try{if(api_is_head_of_service($db,$actor,$sessionId)){$pending=$db->prepare("SELECT COUNT(*) AS total,MAX(requested_at) AS latest FROM check_in_requests WHERE service_session_id=? AND status='PENDING'");$pending->execute([$sessionId]);$request=$pending->fetch()?:[];$requestCount=(int)($request['total']??0);if($requestCount){$latest=(string)($request['latest']??'pending');$items[]=['id'=>"pickup-code-request-{$sessionId}-{$latest}",'kind'=>'PICKUP','severity'=>'URGENT','title'=>"{$requestCount} parent ".($requestCount===1?'is':'are').' waiting for pickup-code approval','detail'=>($service['name']??'Selected service').' · Review the parent check-in request now','href'=>'/account/check-in'];}}}catch(Throwable){}}
    try{api_followup_sync_cases($db,$campus);$where=['fc.campus_id=?',"fc.status IN ('NEEDS_FOLLOW_UP','COULDNT_REACH')"];$params=[$campus];if(!$followUpLead){$where[]='fc.owner_staff_user_id=?';$params[]=$actor['id'];}$filter=' WHERE '.implode(' AND ',$where);$cases=$db->prepare("SELECT COUNT(DISTINCT fc.id) AS cases,COUNT(DISTINCT cc.child_id) AS children FROM follow_up_cases fc JOIN follow_up_case_children cc ON cc.follow_up_case_id=fc.id$filter");$cases->execute($params);$follow=$cases->fetch()?:[];$caseCount=(int)($follow['cases']??0);$childCount=(int)($follow['children']??0);if($caseCount)$items[]=['id'=>"follow-up-{$caseCount}-{$childCount}",'kind'=>'FOLLOW_UP','severity'=>'HIGH','title'=>"{$childCount} child".($childCount===1?' needs':'ren need').' follow-up','detail'=>$followUpLead?"{$caseCount} family ".($caseCount===1?'case remains':'cases remain').' across the follow-up team':"{$caseCount} family ".($caseCount===1?'case is':'cases are').' assigned to you','href'=>'/account/relations'];}catch(Throwable){}
    if($isSuper){$classes=$db->prepare('SELECT COUNT(*) FROM children c JOIN families f ON f.id=c.family_id WHERE f.campus_id=? AND c.is_active=1 AND c.class_assignment_required=1');$classes->execute([$campus]);$count=(int)$classes->fetchColumn();if($count)$items[]=['id'=>"class-assignment-{$count}",'kind'=>'CLASS','severity'=>'HIGH','title'=>"{$count} child".($count===1?' needs':'ren need').' a class assignment','detail'=>'New registrations need a classroom before their next service','href'=>'/account/children'];$month=date('Y-m');try{$unfilled=$db->prepare("SELECT COUNT(*) FROM roster_duty_slots rds JOIN roster_month_states rms ON rms.campus_id=rds.campus_id AND rms.roster_month=? WHERE rds.campus_id=? AND rds.assignment_date>=? AND rds.assignment_date<DATE_ADD(?,INTERVAL 1 MONTH) AND rds.assignment_id IS NULL");$start=$month.'-01';$unfilled->execute([$start,$campus,$start,$start]);$count=(int)$unfilled->fetchColumn();if($count)$items[]=['id'=>"roster-gap-{$month}-{$count}",'kind'=>'ROSTER','severity'=>'MEDIUM','title'=>"{$count} roster ".($count===1?'duty is':'duties are').' unfilled','detail'=>'This month’s team plan still has open responsibilities','href'=>'/account/roster'];}catch(Throwable){}}
    /* Birthday reminders are generated at read time, so every active teammate sees
       the same greeting without relying on a fragile browser-only timer. */
    try{$birthdays=$db->prepare("SELECT s.id,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,''),' ',COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))),''),s.name) AS teacherName FROM staff_users s JOIN teacher_profiles p ON p.staff_user_id=s.id WHERE s.campus_id=? AND s.is_active=1 AND p.birth_date IS NOT NULL AND DATE_FORMAT(p.birth_date,'%m-%d')=DATE_FORMAT(CURDATE(),'%m-%d') ORDER BY teacherName");$birthdays->execute([$campus]);foreach($birthdays->fetchAll() as $birthday){$items[]=['id'=>'birthday-'.(int)$birthday['id'].'-'.date('Ymd'),'kind'=>'TEAM','severity'=>'MEDIUM','title'=>'Happy birthday, '.$birthday['teacherName'].'!','detail'=>'Celebrate a member of the TribePetra Kids team today.','href'=>'/account/team?member='.(int)$birthday['id']];}}catch(Throwable){}
    /* An in-app prompt becomes visible to an onboarded colleague after their shared
       service has ended, until leadership completes that probation-week review. */
    try{$now=new DateTimeImmutable('now',new DateTimeZone('Africa/Lagos'));if($now->format('w')==='0'){$due=$db->prepare("SELECT ra2.user_id AS probationTeacherId,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(tp.title,''),' ',COALESCE(tp.first_name,''),' ',COALESCE(tp.last_name,''))),''),trainee.name) AS teacherName,ra2.assignment_date AS serviceDate,ss.service_type AS serviceType FROM roster_assignments ra1 JOIN roster_assignments ra2 ON ra2.assignment_date=ra1.assignment_date AND COALESCE(ra2.service_session_id,0)=COALESCE(ra1.service_session_id,0) JOIN staff_users trainee ON trainee.id=ra2.user_id JOIN staff_onboarding_profiles trainee_onboarding ON trainee_onboarding.staff_user_id=trainee.id AND trainee_onboarding.onboarding_status='PROBATION' JOIN staff_onboarding_profiles reviewer_onboarding ON reviewer_onboarding.staff_user_id=ra1.user_id AND reviewer_onboarding.onboarding_status='ONBOARDED' LEFT JOIN teacher_profiles tp ON tp.staff_user_id=trainee.id LEFT JOIN service_sessions ss ON ss.id=ra2.service_session_id LEFT JOIN staff_probation_weekly_logs review ON review.staff_user_id=ra2.user_id AND review.service_date=ra2.assignment_date AND review.super_admin_signed_at IS NOT NULL WHERE ra1.user_id=? AND ra1.status NOT IN ('CANCELLED','REPLACED','ABSENT') AND ra2.status NOT IN ('CANCELLED','REPLACED','ABSENT') AND review.id IS NULL AND ra2.assignment_date=CURDATE()");$due->execute([$actor['id']]);foreach($due->fetchAll() as $review){$cutoff=($review['serviceType']??'')==='SECOND_SERVICE'?'12:30:00':'10:30:00';if($now>=new DateTimeImmutable($review['serviceDate'].' '.$cutoff,new DateTimeZone('Africa/Lagos')))$items[]=['id'=>'probation-sign-'.(int)$review['probationTeacherId'].'-'.$review['serviceDate'],'kind'=>'TEAM','severity'=>'HIGH','title'=>'Sign '.$review['teacherName']."’s onboarding review",'detail'=>'You served together today. Please add your attendance sign-off.','href'=>'/account/team?member='.(int)$review['probationTeacherId']];}}}catch(Throwable){}
    $rank=['URGENT'=>0,'HIGH'=>1,'MEDIUM'=>2];usort($items,fn($a,$b)=>($rank[$a['severity']]??9)<=>($rank[$b['severity']]??9));api_ok(['items'=>$items,'scope'=>$isSuper?'CAMPUS':'ASSIGNED_CLASSES','serviceSessionId'=>$sessionId?:null]);
}
function api_is_head_of_service(PDO $db, array $actor, int $serviceSessionId): bool {
    $s=$db->prepare("SELECT 1 FROM roster_assignments ra JOIN duty_types dt ON dt.id=ra.duty_type_id JOIN service_sessions ss ON ss.id=? WHERE ra.user_id=? AND dt.code IN ('HEAD_OF_SERVICE','ASSISTANT_HEAD_OF_SERVICE_1','ASSISTANT_HEAD_OF_SERVICE_2') AND ra.status NOT IN ('CANCELLED','REPLACED','ABSENT') AND (ra.service_session_id=? OR (ra.service_session_id IS NULL AND ra.assignment_date=ss.service_date)) LIMIT 1");
    $s->execute([$serviceSessionId,$actor['id'],$serviceSessionId]); return (bool)$s->fetchColumn();
}
function api_can_operate_sunday(PDO $db, array $actor, int $serviceSessionId): bool {
    if($actor['access_level']==='TPK_SUPER_ADMIN')return true;
    $s=$db->prepare("SELECT 1 FROM roster_assignments ra JOIN duty_types dt ON dt.id=ra.duty_type_id JOIN service_sessions ss ON ss.id=? WHERE ra.user_id=? AND dt.code IN ('ASSEMBLY','HEAD_OF_SERVICE','ASSISTANT_HEAD_OF_SERVICE_1','ASSISTANT_HEAD_OF_SERVICE_2') AND ra.status NOT IN ('CANCELLED','REPLACED','ABSENT') AND (ra.service_session_id=? OR (ra.service_session_id IS NULL AND ra.assignment_date=ss.service_date)) LIMIT 1");
    $s->execute([$serviceSessionId,$actor['id'],$serviceSessionId]);return(bool)$s->fetchColumn();
}
function api_checkin_window_open(PDO $db,int $serviceSessionId): bool {
    $s=$db->prepare("SELECT service_date AS serviceDate,service_type AS serviceType FROM service_sessions WHERE id=? AND service_type IN ('FIRST_SERVICE','SECOND_SERVICE')");$s->execute([$serviceSessionId]);$service=$s->fetch();if(!$service)return false;
    $now=new DateTimeImmutable('now',new DateTimeZone('Africa/Lagos'));if($now->format('Y-m-d')!==$service['serviceDate']||$now->format('w')!=='0')return false;
    $opens=$service['serviceType']==='FIRST_SERVICE'?'06:00:00':'10:30:00';return $now>=new DateTimeImmutable($service['serviceDate'].' '.$opens,new DateTimeZone('Africa/Lagos'));
}
function api_can_operate_checkin(PDO $db,array $actor,int $serviceSessionId): bool { return api_checkin_window_open($db,$serviceSessionId)&&api_can_operate_sunday($db,$actor,$serviceSessionId); }
function api_checkin_request_rows(PDO $db, int $sessionId): array {
    $s=$db->prepare("SELECT r.id,r.status,r.requested_at AS requestedAt,r.approved_at AS approvedAt,r.child_ids_json,r.request_token AS requestToken,g.first_name AS guardianFirstName,g.last_name AS guardianLastName,g.phone AS guardianPhone,f.surname,pc.display_code AS pickupCode,pc.qr_token AS qrToken FROM check_in_requests r JOIN guardians g ON g.id=r.guardian_id JOIN families f ON f.id=r.family_id LEFT JOIN service_pickup_codes pc ON pc.id=r.pickup_code_id WHERE r.service_session_id=? ORDER BY r.status='PENDING' DESC,r.requested_at DESC");
    $s->execute([$sessionId]);$rows=$s->fetchAll();
    foreach($rows as &$row){$ids=json_decode((string)$row['child_ids_json'],true);$ids=is_array($ids)?array_values(array_filter(array_map('intval',$ids))):[];$row['children']=[];if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$c=$db->prepare("SELECT id,first_name AS firstName,last_name AS lastName FROM children WHERE id IN ($marks) ORDER BY first_name");$c->execute($ids);$row['children']=$c->fetchAll();}unset($row['child_ids_json']);$row['ticketUrl']=!empty($row['qrToken'])?tpk_pickup_ticket_url($row['qrToken']):null;unset($row['qrToken']);}
    unset($row);return $rows;
}
function api_checkin_requests(PDO $db): never {
    $actor=api_actor($db);$sessionId=(int)($_GET['serviceSessionId']??0);
    if(!$sessionId){$s=$db->prepare('SELECT id FROM service_sessions WHERE campus_id=? AND is_open=1 AND service_date=CURDATE() ORDER BY starts_at DESC LIMIT 1');$s->execute([$actor['campus_id']]);$sessionId=(int)$s->fetchColumn();}
    if(!$sessionId) api_ok(['serviceSessionId'=>null,'canApprove'=>false,'items'=>[]]);
    $canApprove=api_can_operate_checkin($db,$actor,$sessionId);
    if(!$canApprove) api_error('FORBIDDEN','Check-in opens at 6:00 AM for First Service and 10:30 AM for Second Service. Once open, only the assigned service lead or a Super Admin can approve requests.',403);
    api_ok(['serviceSessionId'=>$sessionId,'canApprove'=>$canApprove,'items'=>api_checkin_request_rows($db,$sessionId)]);
}
function api_approve_checkin_request(PDO $db, int $requestId): never {
    $actor=api_actor($db);$db->beginTransaction();
    try {
        $s=$db->prepare('SELECT r.*,ss.campus_id FROM check_in_requests r JOIN service_sessions ss ON ss.id=r.service_session_id WHERE r.id=? FOR UPDATE');$s->execute([$requestId]);$request=$s->fetch();
        if(!$request || (int)$request['campus_id']!==(int)$actor['campus_id']) { $db->rollBack(); api_error('CHECKIN_REQUEST_NOT_FOUND','This check-in request is not available.',404); }
        if(!api_can_operate_checkin($db,$actor,(int)$request['service_session_id'])) { $db->rollBack(); api_error('FORBIDDEN','Check-in is not open yet, or you are not assigned to operate this service.',403); }
        if($request['status']!=='PENDING') { $db->rollBack(); api_error('CHECKIN_REQUEST_ALREADY_DECIDED','This request has already been '.$request['status'].'.',409); }
        $ids=json_decode((string)$request['child_ids_json'],true);$ids=is_array($ids)?array_values(array_filter(array_map('intval',$ids))):[];
        if(!$ids){$db->rollBack();api_error('CHECKIN_REQUEST_INVALID','This request has no children.',422);}
        $marks=implode(',',array_fill(0,count($ids),'?'));$children=$db->prepare("SELECT id,class_id,is_first_visit,first_name,last_name FROM children WHERE family_id=? AND id IN ($marks) AND is_active=1 FOR UPDATE");$children->execute(array_merge([(int)$request['family_id']],$ids));$rows=$children->fetchAll();
        if(count($rows)!==count($ids)){$db->rollBack();api_error('CHECKIN_REQUEST_INVALID','One or more children are no longer available for this request.',422);}
        foreach($rows as $child)if(!$child['class_id']){$db->rollBack();api_error('CLASS_ASSIGNMENT_REQUIRED',trim($child['first_name'].' '.$child['last_name']).' needs a class assignment before approval.',409);}
        foreach($rows as $child){$db->prepare("INSERT INTO attendance(service_session_id,check_in_request_id,child_id,class_id,status,source,is_first_visit) VALUES(?,?,?,?,'CHECKED_IN','PARENT_QR',?) ON DUPLICATE KEY UPDATE check_in_request_id=VALUES(check_in_request_id),status=status")->execute([(int)$request['service_session_id'],$requestId,(int)$child['id'],(int)$child['class_id'],(int)$child['is_first_visit']]);}
        $pickup=tpk_issue_pickup_code($db,(int)$request['service_session_id'],(int)$request['family_id'],(int)$request['guardian_id']);
        $db->prepare("UPDATE check_in_requests SET status='APPROVED',approved_at=NOW(),approved_by_staff_user_id=?,pickup_code_id=? WHERE id=?")->execute([$actor['id'],$pickup['id'],$requestId]);
        api_audit($db,$actor,'CHECKIN_REQUEST_APPROVED','CheckInRequest',$requestId,['pickupCode'=>$pickup['code'],'children'=>array_column($rows,'id')]);
        $phone=$db->prepare('SELECT phone,secondary_phone FROM guardians WHERE id=?');$phone->execute([(int)$request['guardian_id']]);$guardian=$phone->fetch()?:[];
        $db->commit();tpk_send_pickup_code($db,(int)$pickup['id'],[$guardian['phone']??null,$guardian['secondary_phone']??null],$pickup['code'],$pickup['ticketUrl']);
        api_ok(['id'=>$requestId,'status'=>'APPROVED','pickupCode'=>$pickup['code'],'pickupTicketUrl'=>$pickup['ticketUrl'],'childrenApproved'=>count($rows)]);
    } catch (Throwable $e) { if($db->inTransaction())$db->rollBack(); throw $e; }
}
function api_checkins(PDO $db): never {
    $actor=api_actor($db);$allowed=api_permitted_class_ids($db,$actor);$sessionId=(int)($_GET['serviceSessionId']??0);
    if(!$sessionId){$current=$db->prepare('SELECT id FROM service_sessions WHERE campus_id=? AND is_open=1 AND service_date=CURDATE() ORDER BY starts_at DESC LIMIT 1');$current->execute([$actor['campus_id']]);$sessionId=(int)$current->fetchColumn();}
    if(!$sessionId)api_ok(['serviceSessionId'=>null,'canOperate'=>false,'items'=>[]]);$canOperate=api_can_operate_checkin($db,$actor,$sessionId);$where=['a.service_session_id=?'];$params=[$sessionId];if($allowed!==null){if(!$allowed)api_ok(['serviceSessionId'=>$sessionId,'canOperate'=>$canOperate,'items'=>[]]);$where[]='a.class_id IN ('.implode(',',array_fill(0,count($allowed),'?')).')';$params=array_merge($params,$allowed);}
    if(($q=trim((string)($_GET['search']??'')))!==''){$where[]='(c.first_name LIKE ? OR c.last_name LIKE ? OR g.first_name LIKE ? OR g.last_name LIKE ?)';$params=array_merge($params,["%$q%","%$q%","%$q%","%$q%"]);}
    $sql="SELECT a.id,c.id AS childId,c.first_name AS firstName,c.last_name AS lastName,c.gender,cl.name AS className,a.status,a.checked_in_at AS checkedInAt,a.is_first_visit AS firstVisit,g.first_name AS guardianFirstName,g.last_name AS guardianLastName,cir.id AS checkInRequestId,pc.qr_token AS ticketToken FROM attendance a JOIN children c ON c.id=a.child_id LEFT JOIN classes cl ON cl.id=a.class_id LEFT JOIN child_guardians cg ON cg.child_id=c.id AND cg.is_primary=1 LEFT JOIN guardians g ON g.id=cg.guardian_id LEFT JOIN check_in_requests cir ON cir.id=a.check_in_request_id LEFT JOIN service_pickup_codes pc ON pc.id=cir.pickup_code_id WHERE ".implode(' AND ',$where).' ORDER BY a.checked_in_at DESC';$s=$db->prepare($sql);$s->execute($params);$items=$s->fetchAll();foreach($items as &$item){$item['checkInFormUrl']=!empty($item['ticketToken'])?tpk_pickup_ticket_url($item['ticketToken']):null;unset($item['ticketToken']);}unset($item);api_ok(['serviceSessionId'=>$sessionId,'canOperate'=>$canOperate,'items'=>$items]);
}
/** A staff-entered arrival is intentionally separate from the parent approval queue:
 * a logged-in TPK team member has checked the family in at the desk and can hand
 * the pickup ticket over immediately. */
function api_assisted_checkin(PDO $db): never {
