function api_assisted_pickup_lookup(PDO $db): never {
    $actor=api_actor($db);$v=api_input();$first=trim((string)($v['firstName']??''));$last=trim((string)($v['lastName']??''));$birthDate=trim((string)($v['dateOfBirth']??''));
    if($first===''||$last===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$birthDate)) api_error('VALIDATION_ERROR','Enter the child’s first name, last name, and date of birth.',422);
