function api_pickup_dashboard(PDO $db): never {
    $actor=api_actor($db);$serviceId=(int)($_GET['serviceSessionId']??0);$scope=strtoupper((string)($_GET['scope']??'CURRENT'));$month=trim((string)($_GET['month']??''));$year=trim((string)($_GET['year']??''));$zone=new DateTimeZone('Africa/Lagos');$today=new DateTimeImmutable('today',$zone);$current=null;$baseWhere=["ss.campus_id=?","ss.service_type IN ('FIRST_SERVICE','SECOND_SERVICE')"];$baseParams=[$actor['campus_id']];
    if($scope==='CURRENT'){$session=$serviceId?$db->prepare("SELECT id,name,service_date AS serviceDate FROM service_sessions WHERE id=? AND campus_id=? AND service_type IN ('FIRST_SERVICE','SECOND_SERVICE') LIMIT 1"):$db->prepare("SELECT id,name,service_date AS serviceDate FROM service_sessions WHERE campus_id=? AND service_type IN ('FIRST_SERVICE','SECOND_SERVICE') ORDER BY is_open DESC,service_date DESC,starts_at DESC,id DESC LIMIT 1");$session->execute($serviceId?[$serviceId,$actor['campus_id']]:[$actor['campus_id']]);$current=$session->fetch();if(!$current)api_ok(['service'=>null,'canOperate'=>false,'checkedIn'=>0,'pickedUp'=>0,'stillPresent'=>0,'items'=>[],'scope'=>$scope]);$baseWhere[]='a.service_session_id=?';$baseParams[]=(int)$current['id'];}
    elseif($scope==='LAST_SUNDAY'){$last=$today->modify('last sunday')->format('Y-m-d');$baseWhere[]='ss.service_date=?';$baseParams[]=$last;}
    elseif($scope==='MONTH'){if(!preg_match('/^\d{4}-\d{2}$/',$month))api_error('VALIDATION_ERROR','Choose a valid history month.',422);$from=$month.'-01';$baseWhere[]='ss.service_date>=? AND ss.service_date<DATE_ADD(?,INTERVAL 1 MONTH)';$baseParams[]=$from;$baseParams[]=$from;}
    elseif($scope==='YEAR'){if(!preg_match('/^\d{4}$/',$year))api_error('VALIDATION_ERROR','Choose a valid history year.',422);$from=$year.'-01-01';$baseWhere[]='ss.service_date>=? AND ss.service_date<DATE_ADD(?,INTERVAL 1 YEAR)';$baseParams[]=$from;$baseParams[]=$from;}
    else api_error('VALIDATION_ERROR','Choose a valid pickup history filter.',422);
    $countSql="SELECT SUM(a.status='CHECKED_IN') AS checkedIn,SUM(a.status='PICKED_UP') AS pickedUp FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id WHERE ".implode(' AND ',$baseWhere);$counts=$db->prepare($countSql);$counts->execute($baseParams);$summary=$counts->fetch()?:[];
    $where=$baseWhere;$params=$baseParams;if(($search=trim((string)($_GET['search']??'')))!==''){$where[]='(c.first_name LIKE ? OR c.last_name LIKE ? OR EXISTS (SELECT 1 FROM child_guardians search_cg JOIN guardians search_g ON search_g.id=search_cg.guardian_id WHERE search_cg.child_id=c.id AND (search_g.first_name LIKE ? OR search_g.last_name LIKE ? OR search_g.phone LIKE ?)))';$params=array_merge($params,["%$search%","%$search%","%$search%","%$search%","%$search%"]);}if(($classId=(int)($_GET['classId']??0))>0){$where[]='a.class_id=?';$params[]=$classId;}
    $status=strtoupper((string)($_GET['status']??'PRESENT'));if(!in_array($status,['PRESENT','COMPLETED'],true))$status='PRESENT';$where[]=$status==='COMPLETED'?"a.status='PICKED_UP'":"a.status='CHECKED_IN'";
    $sql="SELECT a.id AS attendanceId,a.status,a.checked_in_at AS checkedInAt,a.picked_up_at AS pickedUpAt,ss.service_date AS serviceDate,ss.name AS serviceName,c.id AS childId,c.first_name AS firstName,c.last_name AS lastName,cl.name AS className,COALESCE(guards.guardianName,'—') AS guardianName,COALESCE(guards.guardianPhone,'') AS guardianPhone,pc.display_code AS pickupCode,pc.qr_token AS pickupTicketToken FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id JOIN children c ON c.id=a.child_id LEFT JOIN classes cl ON cl.id=a.class_id LEFT JOIN service_pickup_codes pc ON pc.service_session_id=a.service_session_id AND pc.family_id=c.family_id LEFT JOIN (SELECT cg.child_id,GROUP_CONCAT(DISTINCT TRIM(CONCAT(g.first_name,' ',g.last_name)) ORDER BY cg.is_primary DESC,g.first_name SEPARATOR ' · ') AS guardianName,GROUP_CONCAT(DISTINCT g.phone ORDER BY cg.is_primary DESC,g.first_name SEPARATOR ' · ') AS guardianPhone FROM child_guardians cg JOIN guardians g ON g.id=cg.guardian_id GROUP BY cg.child_id) guards ON guards.child_id=c.id WHERE ".implode(' AND ',$where).' ORDER BY ss.service_date DESC,'.($status==='COMPLETED'?'a.picked_up_at DESC':'a.checked_in_at ASC').',c.first_name LIMIT 500';$items=$db->prepare($sql);$items->execute($params);$items=$items->fetchAll();foreach($items as &$item){$item['pickupTicketUrl']=!empty($item['pickupTicketToken'])?tpk_pickup_ticket_url($item['pickupTicketToken']):null;unset($item['pickupTicketToken']);}unset($item);
    api_ok(['service'=>$current,'canOperate'=>$current?api_can_operate_sunday($db,$actor,(int)$current['id']):false,'checkedIn'=>(int)($summary['checkedIn']??0)+(int)($summary['pickedUp']??0),'pickedUp'=>(int)($summary['pickedUp']??0),'stillPresent'=>(int)($summary['checkedIn']??0),'items'=>$items,'queue'=>$status,'scope'=>$scope,'month'=>$scope==='MONTH'?$month:null,'year'=>in_array($scope,['MONTH','YEAR'],true)?substr($scope==='MONTH'?$month:$year,0,4):null]);
}
function api_set_access(PDO $db,int $id): never { $actor=api_actor($db,true);if($id===(int)$actor['id'])api_error('FORBIDDEN','A Super Admin cannot change their own access level.',403);$v=api_input();$next=$v['accessLevel']??'';if(!in_array($next,['TPK_SUPER_ADMIN','TPK_FOLLOW_UP_ADMIN','TPK_ADMIN'],true))api_error('VALIDATION_ERROR','Choose a valid team access level.',422);$s=$db->prepare('SELECT access_level FROM staff_users WHERE id=? AND campus_id=?');$s->execute([$id,$actor['campus_id']]);$previous=$s->fetchColumn();if($previous===false)api_error('STAFF_NOT_FOUND','Team member not found.',404);if($previous===$next)api_ok(['id'=>$id,'accessLevel'=>$next]);$db->beginTransaction();try{$db->prepare('UPDATE staff_users SET access_level=? WHERE id=?')->execute([$next,$id]);$db->prepare('INSERT INTO staff_access_audits(staff_user_id,previous_access_level,next_access_level,changed_by_staff_user_id) VALUES(?,?,?,?)')->execute([$id,$previous,$next,$actor['id']]);api_audit($db,$actor,'STAFF_ACCESS_UPDATED','StaffUser',$id,['from'=>$previous,'to'=>$next]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}api_ok(['id'=>$id,'accessLevel'=>$next]); }
function api_my_profile(PDO $db): never {
    $actor=api_actor($db);$s=$db->prepare('SELECT s.id AS staffUserId,s.email,s.team_status AS teamStatus,s.joined_at AS joinedAt,c.name AS campus,p.title,p.gender AS gender,p.first_name AS firstName,p.last_name AS lastName,p.birth_date AS birthDate,p.whatsapp_number AS whatsappNumber,p.mobile_number AS mobileNumber,p.residential_address AS residentialAddress,p.emergency_contact AS emergencyContact,p.emergency_relationship AS emergencyRelationship,p.emergency_phone AS emergencyPhone,p.profile_image_url AS profileImageUrl,p.whatsapp_verified_at AS whatsappVerifiedAt FROM staff_users s JOIN teacher_profiles p ON p.staff_user_id=s.id JOIN campuses c ON c.id=s.campus_id WHERE s.id=?');$s->execute([$actor['id']]);$profile=$s->fetch();if(!$profile)api_error('PROFILE_NOT_FOUND','Your staff profile is not available.',404);
