    foreach($allowed as $input=>$column)if(array_key_exists($input,$v)){if($input==='gender'){ $gender=strtoupper(trim((string)$v[$input]));if(!in_array($gender,['FEMALE','MALE'],true))api_error('VALIDATION_ERROR','Choose Female or Male.',422);$profileSets[]='gender=?';$params[]=$gender;$profileSets[]='title=?';$params[]=$gender==='FEMALE'?'Auntie':'Uncle';continue;}if($input==='email'&&!filter_var($v[$input],FILTER_VALIDATE_EMAIL))api_error('VALIDATION_ERROR','Enter a valid email address.',422);if($input==='mobileNumber'&&$v[$input]!==null&&$v[$input]!==''){ $number=tpk_normalize_nigerian_phone($v[$input]);if(!$number)api_error('VALIDATION_ERROR','Enter a valid Nigerian mobile number.',422);$profileSets[]='mobile_number=?';$params[]=$number;$profileSets[]='mobile_number_normalized=?';$params[]=$number;continue;}if($input==='email'){$userSets[]='email=?';$userParams[]=strtolower(trim($v[$input]));}else{$profileSets[]="$column=?";$params[]=$v[$input];}}
