function api_followup_sync_cases(PDO $db,int $campusId): void {
    /* Only unresolved absence tasks become cases. Children without a trigger are
       deliberately excluded, even when they share the same family. */
    $tasks=$db->prepare("SELECT t.id,t.child_id,c.family_id,t.assigned_to_staff_user_id FROM follow_up_tasks t JOIN children c ON c.id=t.child_id WHERE t.campus_id=? AND t.task_type IN ('MISSED_SERVICE','TWO_WEEK_ABSENCE') AND t.status IN ('OPEN','IN_PROGRESS') AND NOT EXISTS(SELECT 1 FROM follow_up_case_children cc WHERE cc.source_task_id=t.id)");
    $tasks->execute([$campusId]);foreach($tasks->fetchAll() as $task){$existing=$db->prepare("SELECT id FROM follow_up_cases WHERE campus_id=? AND family_id=? AND status IN ('NEEDS_FOLLOW_UP','CONTACTED','COULDNT_REACH') ORDER BY updated_at DESC LIMIT 1");$existing->execute([$campusId,$task['family_id']]);$caseId=(int)$existing->fetchColumn();if(!$caseId){$insert=$db->prepare("INSERT INTO follow_up_cases(campus_id,family_id,owner_staff_user_id) VALUES(?,?,?)");$insert->execute([$campusId,$task['family_id'],$task['assigned_to_staff_user_id']?:null]);$caseId=(int)$db->lastInsertId();$db->prepare("INSERT INTO follow_up_case_events(follow_up_case_id,event_type,notes) VALUES(?,'CASE_CREATED',?)")->execute([$caseId,'Created from attendance follow-up trigger.']);}$db->prepare('INSERT IGNORE INTO follow_up_case_children(follow_up_case_id,child_id,source_task_id) VALUES(?,?,?)')->execute([$caseId,$task['child_id'],$task['id']]);}
}
function api_followup_case_allowed(PDO $db,array $actor,int $caseId,bool $sharedView = false): array {
    $s=$db->prepare('SELECT fc.id,fc.campus_id AS campusId,fc.family_id AS familyId,fc.owner_staff_user_id AS ownerId,fc.status,fc.leadership_status AS leadershipStatus,fc.reason,fc.notes,fc.expected_back AS expectedBack,fc.last_contacted_at AS lastContactedAt,fc.created_at AS createdAt,f.surname AS familyName FROM follow_up_cases fc JOIN families f ON f.id=fc.family_id WHERE fc.id=? AND fc.campus_id=?');
    $s->execute([$caseId,$actor['campus_id']]);$case=$s->fetch();
    if(!$case) api_error('FOLLOW_UP_NOT_FOUND','This follow-up case is not available.',404);
    if(!api_is_followup_lead($actor) && (int)$case['ownerId'] !== (int)$actor['id']) api_error('FORBIDDEN','This follow-up has not been assigned to you.',403);
    return $case;
}
function api_followup_summary(PDO $db): never {
    $actor=api_actor($db);api_followup_sync_cases($db,(int)$actor['campus_id']);$where=['fc.campus_id=?'];$params=[$actor['campus_id']];
    if(!api_is_followup_lead($actor)){$where[]='fc.owner_staff_user_id=?';$params[]=$actor['id'];}
    $filter=' WHERE '.implode(' AND ',$where);$s=$db->prepare("SELECT COUNT(*) AS total,SUM(fc.status='NEEDS_FOLLOW_UP') AS needsFollowUp,SUM(fc.status='CONTACTED') AS contacted,SUM(fc.status='COULDNT_REACH') AS couldntReach,SUM(fc.leadership_status IN ('SENT','LEADERSHIP_ATTENTION_REQUIRED')) AS needsLeadership FROM follow_up_cases fc$filter");$s->execute($params);$row=$s->fetch()?:[];$kids=$db->prepare("SELECT COUNT(DISTINCT cc.child_id) FROM follow_up_cases fc JOIN follow_up_case_children cc ON cc.follow_up_case_id=fc.id$filter AND fc.status='NEEDS_FOLLOW_UP'");$kids->execute($params);api_ok(['needFollowUp'=>(int)($row['needsFollowUp']??0),'contacted'=>(int)($row['contacted']??0),'couldntReach'=>(int)($row['couldntReach']??0),'needsLeadership'=>(int)($row['needsLeadership']??0),'childrenAcrossNeedFollowUp'=>(int)$kids->fetchColumn(),'canManage'=>api_is_followup_lead($actor)]);
}
function api_followups(PDO $db): never {
    $actor=api_actor($db);api_followup_sync_cases($db,(int)$actor['campus_id']);[$page,$limit,$offset]=api_page();$where=['fc.campus_id=?'];$params=[$actor['campus_id']];$canManage=api_is_followup_lead($actor);
    if(!$canManage){$where[]='fc.owner_staff_user_id=?';$params[]=$actor['id'];}
    $tab=trim((string)($_GET['tab']??'needs'));if($tab==='contacted')$where[]="fc.status='CONTACTED'";elseif($tab==='leadership')$where[]="fc.leadership_status IN ('SENT','LEADERSHIP_ATTENTION_REQUIRED')";else $where[]="fc.status IN ('NEEDS_FOLLOW_UP','COULDNT_REACH')";
    if(($q=trim((string)($_GET['search']??'')))!==''){$needle='%'.$q.'%';$where[]='(f.surname LIKE ? OR EXISTS(SELECT 1 FROM follow_up_case_children scc JOIN children sc ON sc.id=scc.child_id WHERE scc.follow_up_case_id=fc.id AND (sc.first_name LIKE ? OR sc.last_name LIKE ?)) OR EXISTS(SELECT 1 FROM guardians sg WHERE sg.family_id=fc.family_id AND (sg.first_name LIKE ? OR sg.last_name LIKE ? OR sg.phone LIKE ?)))';$params=array_merge($params,[$needle,$needle,$needle,$needle,$needle,$needle]);}
    if(($classId=(int)($_GET['classId']??0))>0){$where[]='EXISTS(SELECT 1 FROM follow_up_case_children cc JOIN children c ON c.id=cc.child_id WHERE cc.follow_up_case_id=fc.id AND c.class_id=?)';$params[]=$classId;}
    if(($owner=(int)($_GET['ownerId']??0))>0&&$canManage){$where[]='fc.owner_staff_user_id=?';$params[]=$owner;}
    if(($status=trim((string)($_GET['status']??'')))!==''){if(in_array($status,['NEEDS_FOLLOW_UP','CONTACTED','COULDNT_REACH','RESOLVED'],true)){$where[]='fc.status=?';$params[]=$status;}}
    if(($missed=(int)($_GET['missed']??0))>0){$where[]="(SELECT MAX(CASE t.task_type WHEN 'TWO_WEEK_ABSENCE' THEN 2 ELSE 1 END) FROM follow_up_case_children cc LEFT JOIN follow_up_tasks t ON t.id=cc.source_task_id WHERE cc.follow_up_case_id=fc.id)>=?";$params[]=$missed;}
    $month=(int)($_GET['month']??0);$year=(int)($_GET['year']??0);if($month>0||$year>0){if($month<1||$month>12||$year<2020||$year>2100)api_error('VALIDATION_ERROR','Choose a valid follow-up month and year.',422);$where[]='EXISTS(SELECT 1 FROM follow_up_case_children fcc JOIN follow_up_tasks ft ON ft.id=fcc.source_task_id JOIN service_sessions fss ON fss.id=ft.service_session_id WHERE fcc.follow_up_case_id=fc.id AND MONTH(fss.service_date)=? AND YEAR(fss.service_date)=?)';$params[]=$month;$params[]=$year;}
    $filter=' WHERE '.implode(' AND ',$where);$count=$db->prepare("SELECT COUNT(*) FROM follow_up_cases fc JOIN families f ON f.id=fc.family_id$filter");$count->execute($params);$total=(int)$count->fetchColumn();
    $sql="SELECT fc.id,fc.family_id AS familyId,fc.status,fc.leadership_status AS leadershipStatus,fc.reason,fc.notes,fc.expected_back AS expectedBack,fc.last_contacted_at AS lastContactedAt,fc.created_at AS createdAt,f.surname AS familyName,COALESCE(owner.name,'Unassigned') AS ownerName,owner.id AS ownerId,pg.id AS guardianId,TRIM(CONCAT(COALESCE(pg.first_name,''),' ',COALESCE(pg.last_name,''))) AS guardianName,pg.phone AS guardianPhone,pg.relationship AS guardianRelationship,COUNT(DISTINCT cc.child_id) AS childrenCount,COALESCE(GROUP_CONCAT(DISTINCT CONCAT(c.id,':',c.first_name,' ',c.last_name) ORDER BY c.first_name SEPARATOR ' | '),'') AS children,COALESCE(GROUP_CONCAT(DISTINCT cl.name ORDER BY cl.display_order SEPARATOR ', '),'—') AS classes,(SELECT MAX(ss.service_date) FROM follow_up_case_children ac JOIN attendance a ON a.child_id=ac.child_id JOIN service_sessions ss ON ss.id=a.service_session_id WHERE ac.follow_up_case_id=fc.id AND a.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP')) AS lastAttended,(SELECT MAX(CASE t.task_type WHEN 'TWO_WEEK_ABSENCE' THEN 2 ELSE 1 END) FROM follow_up_case_children tc LEFT JOIN follow_up_tasks t ON t.id=tc.source_task_id WHERE tc.follow_up_case_id=fc.id) AS missedSundays FROM follow_up_cases fc JOIN families f ON f.id=fc.family_id JOIN follow_up_case_children cc ON cc.follow_up_case_id=fc.id JOIN children c ON c.id=cc.child_id LEFT JOIN classes cl ON cl.id=c.class_id LEFT JOIN guardians pg ON pg.family_id=f.id AND pg.is_primary=1 LEFT JOIN staff_users owner ON owner.id=fc.owner_staff_user_id$filter GROUP BY fc.id,f.id,owner.id,pg.id ORDER BY fc.status='NEEDS_FOLLOW_UP' DESC,fc.last_contacted_at IS NULL DESC,fc.updated_at DESC LIMIT $limit OFFSET $offset";
    $s=$db->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$sender=$db->prepare("SELECT COALESCE(NULLIF(TRIM(CONCAT(COALESCE(profile.title,''),' ',COALESCE(profile.first_name,''),' ',COALESCE(profile.last_name,''))),''),staff.name,'TPK Team') FROM follow_up_case_escalations escalation LEFT JOIN staff_users staff ON staff.id=escalation.sent_by_staff_user_id LEFT JOIN teacher_profiles profile ON profile.staff_user_id=staff.id WHERE escalation.follow_up_case_id=? AND escalation.status='SENT' ORDER BY escalation.sent_at DESC,escalation.id DESC LIMIT 1");foreach($rows as &$row){$sender->execute([(int)$row['id']]);$row['followUpSentBy']=$sender->fetchColumn()?:null;}unset($row);api_ok($rows,200,['page'=>$page,'limit'=>$limit,'total'=>$total,'totalPages'=>max(1,(int)ceil($total/$limit))]);
}
function api_followup(PDO $db,int $id): never {
    $actor=api_actor($db);$case=api_followup_case_allowed($db,$actor,$id,api_method()==='GET');if(api_method()==='GET'){$children=$db->prepare("SELECT c.id,c.first_name AS firstName,c.last_name AS lastName,cl.name AS className,t.id AS sourceTaskId,t.task_type AS taskType,ss.service_date AS missedServiceDate,(SELECT MAX(prev.service_date) FROM attendance a JOIN service_sessions prev ON prev.id=a.service_session_id WHERE a.child_id=c.id AND a.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP')) AS lastAttended FROM follow_up_case_children cc JOIN children c ON c.id=cc.child_id LEFT JOIN classes cl ON cl.id=c.class_id LEFT JOIN follow_up_tasks t ON t.id=cc.source_task_id LEFT JOIN service_sessions ss ON ss.id=t.service_session_id WHERE cc.follow_up_case_id=? ORDER BY c.first_name");$children->execute([$id]);$case['children']=$children->fetchAll();$g=$db->prepare('SELECT id,first_name AS firstName,last_name AS lastName,phone AS primaryPhone,secondary_phone AS secondaryPhone,email,relationship FROM guardians WHERE family_id=? AND is_primary=1 LIMIT 1');$g->execute([$case['familyId']]);$case['primaryContact']=$g->fetch()?:null;$events=$db->prepare("SELECT e.id,e.event_type AS eventType,e.reason,e.notes,e.expected_back AS expectedBack,e.created_at AS createdAt,COALESCE(u.name,'TPK Team') AS staffName FROM follow_up_case_events e LEFT JOIN staff_users u ON u.id=e.staff_user_id WHERE e.follow_up_case_id=? ORDER BY e.created_at DESC");$events->execute([$id]);$case['history']=$events->fetchAll();$esc=$db->prepare("SELECT e.id,e.status,e.note,e.created_at AS createdAt,COALESCE(u.name,'Leadership') AS recipientName FROM follow_up_case_escalations e LEFT JOIN staff_users u ON u.id=e.recipient_staff_user_id WHERE e.follow_up_case_id=? ORDER BY e.created_at DESC");$esc->execute([$id]);$case['escalations']=$esc->fetchAll();api_ok($case);}
    $v=api_input();$event=strtoupper((string)($v['outcome']??''));$map=['CONTACTED'=>['CONTACTED','CONTACTED'],'NO_ANSWER'=>['COULDNT_REACH','NO_ANSWER'],'NUMBER_UNAVAILABLE'=>['COULDNT_REACH','NUMBER_UNAVAILABLE'],'TRY_AGAIN'=>['COULDNT_REACH','TRY_AGAIN'],'RESOLVED'=>['RESOLVED','RESOLVED']];if(!isset($map[$event]))api_error('VALIDATION_ERROR','Choose a valid follow-up outcome.',422);[$status,$eventType]=$map[$event];$reason=trim((string)($v['reason']??''));$notes=trim((string)($v['notes']??''));$expected=trim((string)($v['expectedBack']??''));if($expected!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$expected))api_error('VALIDATION_ERROR','Choose a valid expected return date.',422);$db->beginTransaction();try{$db->prepare('UPDATE follow_up_cases SET status=?,reason=?,notes=?,expected_back=?,last_contacted_at=NOW(),resolved_at=? WHERE id=?')->execute([$status,$reason?:null,$notes?:null,$expected?:null,$status==='RESOLVED'?date('Y-m-d H:i:s'):null,$id]);$db->prepare('INSERT INTO follow_up_case_events(follow_up_case_id,staff_user_id,event_type,reason,notes,expected_back) VALUES(?,?,?,?,?,?)')->execute([$id,$actor['id'],$eventType,$reason?:null,$notes?:null,$expected?:null]);api_audit($db,$actor,'FOLLOW_UP_RECORDED','FollowUpCase',$id,['outcome'=>$event]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}api_ok(['id'=>$id,'status'=>$status]);
}
function api_followup_recipients(PDO $db): never {$actor=api_actor($db);$s=$db->prepare("SELECT s.id,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,''),' ',COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))),''),s.name) AS name,p.mobile_number AS phone FROM staff_users s JOIN teacher_profiles p ON p.staff_user_id=s.id WHERE s.campus_id=? AND s.access_level='TPK_SUPER_ADMIN' AND s.is_active=1 ORDER BY s.name");$s->execute([$actor['campus_id']]);api_ok($s->fetchAll());}
