function api_followup_escalate(PDO $db,int $id): never {$actor=api_actor($db);$case=api_followup_case_allowed($db,$actor,$id);$v=api_input();$ids=array_values(array_unique(array_filter(array_map('intval',$v['recipientIds']??[]))));if(!$ids)api_error('VALIDATION_ERROR','Choose at least one leadership recipient.',422);$note=trim((string)($v['note']??''));$marks=implode(',',array_fill(0,count($ids),'?'));$valid=$db->prepare("SELECT id,name FROM staff_users WHERE campus_id=? AND access_level='TPK_SUPER_ADMIN' AND is_active=1 AND id IN ($marks)");$valid->execute(array_merge([$actor['campus_id']],$ids));$people=$valid->fetchAll();if(count($people)!==count($ids))api_error('VALIDATION_ERROR','Choose active TPK Super Admin recipients.',422);$childLines=$db->prepare("SELECT CONCAT(c.first_name,' ',c.last_name) AS name,cl.name AS className FROM follow_up_case_children cc JOIN children c ON c.id=cc.child_id LEFT JOIN classes cl ON cl.id=c.class_id WHERE cc.follow_up_case_id=?");$childLines->execute([$id]);$children=$childLines->fetchAll();$message="TPK Children Relations Follow-Up\n\nFamily: {$case['familyName']} Family\nChildren: ".implode('; ',array_map(fn($child)=>$child['name'].' — '.($child['className']?:'Class pending'),$children))."\nUpdate: ".($case['notes']?:'Follow-up requires leadership awareness.')."\nFollowed up by: {$actor['name']}";$db->beginTransaction();try{foreach($people as $person)$db->prepare("INSERT INTO follow_up_case_escalations(follow_up_case_id,recipient_staff_user_id,note,status,sent_by_staff_user_id,sent_at) VALUES(?,?,?,'SENT',?,NOW()) ON DUPLICATE KEY UPDATE note=VALUES(note),status='SENT',sent_by_staff_user_id=VALUES(sent_by_staff_user_id),sent_at=NOW()")->execute([$id,$person['id'],$note?:null,$actor['id']]);$db->prepare("UPDATE follow_up_cases SET leadership_status='SENT' WHERE id=?")->execute([$id]);$db->prepare("INSERT INTO follow_up_case_events(follow_up_case_id,staff_user_id,event_type,notes) VALUES(?,?,'ESCALATED',?)")->execute([$id,$actor['id'],$note?:null]);api_audit($db,$actor,'FOLLOW_UP_ESCALATED','FollowUpCase',$id,['recipients'=>$ids]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}$phones=array_values(array_filter(array_map(fn($p)=>tpk_normalize_nigerian_phone($p['phone']??null),$people)));api_ok(['id'=>$id,'leadershipStatus'=>'SENT','message'=>$message,'whatsappUrl'=>$phones?'https://wa.me/'.ltrim($phones[0],'+').'?text='.rawurlencode($message):null]);}
function api_team(PDO $db): never {
    $actor=api_actor($db);$isSuper=$actor['access_level']==='TPK_SUPER_ADMIN';$visibility=$isSuper?'':' AND s.is_active=1';
    $month=trim((string)($_GET['month']??date('Y-m')));if(!preg_match('/^\\d{4}-(0[1-9]|1[0-2])$/',$month))$month=date('Y-m');$week=max(0,min(5,(int)($_GET['week']??0)));
    $monthStart=$month.'-01';$monthEnd=(new DateTimeImmutable($monthStart))->modify('+1 month')->format('Y-m-d');$assignmentStart=$monthStart;$assignmentEnd=$monthEnd;
    /* A service week is a Sunday in the chosen month—not an arbitrary 1–7,
       8–14 calendar slice. September 2026 therefore has Weeks 1–4. */
    $serviceWeeks=[];$monthDate=new DateTimeImmutable($monthStart);$firstSunday=$monthDate->modify('+'.((7-(int)$monthDate->format('w'))%7).' days');for($sunday=$firstSunday;$sunday->format('Y-m-d')<$monthEnd;$sunday=$sunday->modify('+7 days'))$serviceWeeks[]=$sunday->format('Y-m-d');
    if($week>0){$candidate=$serviceWeeks[$week-1]??null;if($candidate){$assignmentStart=$candidate;$assignmentEnd=min($monthEnd,(new DateTimeImmutable($candidate))->modify('+7 days')->format('Y-m-d'));}else{$assignmentStart=$monthEnd;$assignmentEnd=$monthEnd;}}
    $sql="SELECT s.id,s.name,s.email,s.access_level AS accessLevel,s.is_active AS accountActive,s.inactive_reason AS inactiveReason,s.inactive_at AS inactiveAt,s.joined_at AS joinedAt,p.title,p.first_name AS firstName,p.last_name AS lastName,p.gender,p.profile_image_url AS profileImageUrl,p.whatsapp_number AS whatsappNumber,p.mobile_number AS mobileNumber,p.birth_date AS birthDate,p.residential_address AS residentialAddress,p.emergency_contact AS emergencyContact,p.emergency_relationship AS emergencyRelationship,p.emergency_phone AS emergencyPhone,COALESCE(op.onboarding_status,CASE WHEN s.team_status='PROBATION' THEN 'PROBATION' ELSE 'ONBOARDED' END) AS onboardingStatus,COALESCE(op.probation_started_at,DATE(s.joined_at)) AS probationStartedAt,COALESCE(op.probation_target_weeks,4) AS probationTargetWeeks,op.extended_reason AS probationExtensionReason,GROUP_CONCAT(DISTINCT c.name ORDER BY c.name SEPARATOR ', ') AS assignedClasses,(SELECT CONCAT(dt.name,CASE WHEN ac.name IS NULL THEN '' ELSE CONCAT(' · ',ac.name) END) FROM roster_assignments ra JOIN duty_types dt ON dt.id=ra.duty_type_id LEFT JOIN classes ac ON ac.id=ra.class_id WHERE ra.user_id=s.id AND ra.assignment_date>=? AND ra.assignment_date<? AND ra.status NOT IN ('CANCELLED','REPLACED') ORDER BY ra.assignment_date,ra.id LIMIT 1) AS currentAssignment FROM staff_users s JOIN teacher_profiles p ON p.staff_user_id=s.id LEFT JOIN staff_onboarding_profiles op ON op.staff_user_id=s.id LEFT JOIN staff_class_assignments sca ON sca.staff_user_id=s.id AND sca.is_active=1 LEFT JOIN classes c ON c.id=sca.class_id WHERE s.campus_id=?$visibility GROUP BY s.id,s.inactive_reason,s.inactive_at,p.title,p.first_name,p.last_name,p.gender,p.profile_image_url,p.whatsapp_number,p.mobile_number,p.birth_date,p.residential_address,p.emergency_contact,p.emergency_relationship,p.emergency_phone,op.onboarding_status,op.probation_started_at,op.probation_target_weeks,op.extended_reason ORDER BY p.first_name,p.last_name,s.name";
    /* The directory is for planning ahead: show only each person's next duty in
       the chosen month, never a comma-separated history of every role. */
    $upcomingStart=max($assignmentStart,date('Y-m-d'));$s=$db->prepare($sql);$s->execute([$upcomingStart,$assignmentEnd,$actor['campus_id']]);$rows=$s->fetchAll();foreach($rows as &$row){$row['accountActive']=(bool)$row['accountActive'];$row['probationWeek']=$row['onboardingStatus']==='PROBATION'?max(1,min((int)$row['probationTargetWeeks'],(int)(floor((time()-strtotime((string)$row['probationStartedAt']))/604800)+1))):null;if(!$isSuper){unset($row['accessLevel'],$row['email'],$row['mobileNumber'],$row['birthDate'],$row['residentialAddress'],$row['accountActive'],$row['inactiveReason'],$row['inactiveAt'],$row['probationExtensionReason']);}}unset($row);$roles=$db->query("SELECT name FROM duty_types WHERE active=1 ORDER BY id")->fetchAll();api_ok(['members'=>$rows,'roles'=>array_map(fn($role)=>$role['name'],$roles),'permissions'=>['isSuperAdmin'=>$isSuper,'staffUserId'=>(int)$actor['id']],'filters'=>['month'=>$month,'week'=>$week,'serviceWeeks'=>array_map(fn($date,$index)=>['value'=>$index+1,'label'=>'Week '.($index+1),'sunday'=>$date],$serviceWeeks,array_keys($serviceWeeks)),'assignmentStart'=>$upcomingStart,'assignmentEnd'=>$assignmentEnd]]);
}

function api_staff_roster(PDO $db,int $id): never {
    $actor=api_actor($db);$month=max(1,min(12,(int)($_GET['month']??date('n'))));$year=max(2020,min(2100,(int)($_GET['year']??date('Y'))));$start=sprintf('%04d-%02d-01',$year,$month);$end=(new DateTimeImmutable($start))->modify('+1 month')->format('Y-m-d');
    $teacher=$db->prepare('SELECT id FROM staff_users WHERE id=? AND campus_id=?');$teacher->execute([$id,$actor['campus_id']]);if(!$teacher->fetch())api_error('STAFF_NOT_FOUND','This teacher is not available.',404);
    $s=$db->prepare("SELECT ra.id,ra.assignment_date AS assignmentDate,ra.status,dt.name AS dutyName,dt.code AS dutyCode,COALESCE(ss.name,CASE WHEN dt.category='FIRST_SERVICE' THEN 'First Service' WHEN dt.category='SECOND_SERVICE' THEN 'Second Service' ELSE 'Ministry activity' END) AS serviceName,ss.starts_at AS startsAt,c.name AS className FROM roster_assignments ra JOIN duty_types dt ON dt.id=ra.duty_type_id LEFT JOIN service_sessions ss ON ss.id=ra.service_session_id LEFT JOIN classes c ON c.id=ra.class_id WHERE ra.user_id=? AND ra.assignment_date>=? AND ra.assignment_date<? AND ra.status NOT IN ('CANCELLED','REPLACED') ORDER BY ra.assignment_date,ss.starts_at,ra.id");$s->execute([$id,$start,$end]);api_ok(['month'=>$start,'activities'=>$s->fetchAll()]);
}
function api_update_onboarding(PDO $db,int $id): never {
    $actor=api_actor($db,true);if($id===(int)$actor['id'])api_error('FORBIDDEN','Ask another TPK Super Admin to change your onboarding status.',403);$v=api_input();$action=(string)($v['action']??'');$target=$db->prepare('SELECT s.id,s.team_status,COALESCE(op.onboarding_status,CASE WHEN s.team_status=\'PROBATION\' THEN \'PROBATION\' ELSE \'ONBOARDED\' END) AS onboardingStatus,COALESCE(op.probation_target_weeks,4) AS probationTargetWeeks FROM staff_users s LEFT JOIN staff_onboarding_profiles op ON op.staff_user_id=s.id WHERE s.id=? AND s.campus_id=?');$target->execute([$id,$actor['campus_id']]);$member=$target->fetch();if(!$member)api_error('STAFF_NOT_FOUND','Team member not found.',404);$previous=$member['onboardingStatus'];$next=$previous;$weeks=(int)$member['probationTargetWeeks'];$note=trim((string)($v['reason']??''));if($action==='MARK_ONBOARDED'){$next='ONBOARDED';}elseif($action==='START_PROBATION'){$next='PROBATION';$weeks=max(1,min(12,(int)($v['weeks']??4)));}elseif($action==='EXTEND_PROBATION'){$next='PROBATION';$weeks=max(1,min(12,$weeks+max(1,min(8,(int)($v['weeks']??1)))));}else api_error('VALIDATION_ERROR','Choose a valid onboarding action.',422);$db->beginTransaction();try{$profile=$db->prepare("INSERT INTO staff_onboarding_profiles(staff_user_id,onboarding_status,probation_started_at,probation_target_weeks,onboarded_at,extended_reason,updated_by_staff_user_id) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE onboarding_status=VALUES(onboarding_status),probation_started_at=CASE WHEN VALUES(onboarding_status)='PROBATION' AND probation_started_at IS NULL THEN VALUES(probation_started_at) ELSE probation_started_at END,probation_target_weeks=VALUES(probation_target_weeks),onboarded_at=VALUES(onboarded_at),extended_reason=VALUES(extended_reason),updated_by_staff_user_id=VALUES(updated_by_staff_user_id)");$profile->execute([$id,$next,$next==='PROBATION'?date('Y-m-d'):null,$weeks,$next==='ONBOARDED'?date('Y-m-d H:i:s'):null,$note?:null,$actor['id']]);$db->prepare('UPDATE staff_users SET team_status=? WHERE id=?')->execute([$next==='PROBATION'?'PROBATION':'ACTIVE',$id]);$db->prepare('INSERT INTO staff_onboarding_events(staff_user_id,action,previous_status,next_status,note,performed_by_staff_user_id) VALUES(?,?,?,?,?,?)')->execute([$id,$action,$previous,$next,$note?:null,$actor['id']]);api_audit($db,$actor,'STAFF_ONBOARDING_'.$action,'StaffUser',$id,['from'=>$previous,'to'=>$next,'weeks'=>$weeks]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}api_ok(['id'=>$id,'onboardingStatus'=>$next,'probationTargetWeeks'=>$weeks]);
}
function api_probation_staff_can_sign(PDO $db,array $actor,int $staffUserId,string $serviceDate): bool {
    if($actor['access_level']==='TPK_SUPER_ADMIN')return true;
    $s=$db->prepare("SELECT 1 FROM roster_assignments colleague JOIN roster_assignments volunteer ON volunteer.user_id=? AND volunteer.assignment_date=? AND volunteer.status NOT IN ('CANCELLED','REPLACED','ABSENT') WHERE colleague.user_id=? AND colleague.assignment_date=? AND colleague.status NOT IN ('CANCELLED','REPLACED','ABSENT') AND (colleague.service_session_id=volunteer.service_session_id OR colleague.service_session_id IS NULL OR volunteer.service_session_id IS NULL) LIMIT 1");
    $s->execute([$staffUserId,$serviceDate,$actor['id'],$serviceDate]);return(bool)$s->fetchColumn();
}
function api_probation_log(PDO $db,int $id): never {
    $actor=api_actor($db);$s=$db->prepare("SELECT s.id,s.name,p.title,p.first_name AS firstName,p.last_name AS lastName,p.marital_status AS maritalStatus,p.primary_phone AS primaryPhone,p.secondary_phone AS secondaryPhone,s.email,p.birth_date AS birthDate,p.residential_address AS residentialAddress,p.emergency_contact AS emergencyContact,p.emergency_relationship_phone AS emergencyRelationshipPhone,COALESCE(op.onboarding_status,CASE WHEN s.team_status='PROBATION' THEN 'PROBATION' ELSE 'ONBOARDED' END) AS onboardingStatus,COALESCE(op.probation_started_at,DATE(s.joined_at)) AS probationStartedAt,COALESCE(op.probation_target_weeks,4) AS probationTargetWeeks FROM staff_users s JOIN teacher_profiles p ON p.staff_user_id=s.id LEFT JOIN staff_onboarding_profiles op ON op.staff_user_id=s.id WHERE s.id=? AND s.campus_id=?");$s->execute([$id,$actor['campus_id']]);$profile=$s->fetch();if(!$profile)api_error('STAFF_NOT_FOUND','This teacher is not available.',404);if($profile['onboardingStatus']!=='PROBATION')api_error('NOT_ON_PROBATION','This teacher is not currently on probation.',409);
    $logs=$db->prepare("SELECT l.week_number AS weekNumber,l.service_date AS serviceDate,l.service_type AS serviceType,l.tribe_age_group AS tribeAgeGroup,l.lesson_topic_activity AS lessonTopicActivity,l.time_in AS timeIn,l.staff_signed_at AS staffSignedAt,l.super_admin_signed_at AS superAdminSignedAt,COALESCE(staffSigner.name,'Not yet signed') AS staffSignerName,COALESCE(superSigner.name,'Not yet signed') AS superAdminSignerName FROM staff_probation_weekly_logs l LEFT JOIN staff_users staffSigner ON staffSigner.id=l.staff_signed_by_staff_user_id LEFT JOIN staff_users superSigner ON superSigner.id=l.super_admin_signed_by_staff_user_id WHERE l.staff_user_id=? ORDER BY l.week_number");$logs->execute([$id]);$stored=[];foreach($logs->fetchAll() as $log)$stored[(int)$log['weekNumber']]=$log;$start=new DateTimeImmutable((string)$profile['probationStartedAt']);$weeks=[];for($week=1;$week<=(int)$profile['probationTargetWeeks'];$week++){ $row=$stored[$week]??['weekNumber'=>$week,'serviceDate'=>$start->modify('+'.($week-1).' weeks')->format('Y-m-d'),'serviceType'=>null,'tribeAgeGroup'=>null,'lessonTopicActivity'=>null,'timeIn'=>null,'staffSignedAt'=>null,'superAdminSignedAt'=>null,'staffSignerName'=>'Not yet signed','superAdminSignerName'=>'Not yet signed'];$row['canStaffSign']=api_probation_staff_can_sign($db,$actor,$id,(string)$row['serviceDate']);$weeks[]=$row; }
    api_ok(['profile'=>$profile,'weeks'=>$weeks,'isSuperAdmin'=>$actor['access_level']==='TPK_SUPER_ADMIN']);
