function api_sign_probation_log(PDO $db,int $id,int $week): never {
    $actor=api_actor($db);$v=api_input();if($week<1||$week>12)api_error('VALIDATION_ERROR','Choose a valid probation week.',422);$date=trim((string)($v['serviceDate']??''));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))api_error('VALIDATION_ERROR','Choose the service date for this week.',422);$serviceType=(string)($v['serviceType']??'');if(!in_array($serviceType,['FIRST_SERVICE','SECOND_SERVICE'],true))api_error('VALIDATION_ERROR','Choose the service taught for this review.',422);$target=$db->prepare("SELECT COALESCE(op.onboarding_status,CASE WHEN s.team_status='PROBATION' THEN 'PROBATION' ELSE 'ONBOARDED' END) AS onboardingStatus,COALESCE(op.probation_target_weeks,4) AS weeks FROM staff_users s LEFT JOIN staff_onboarding_profiles op ON op.staff_user_id=s.id WHERE s.id=? AND s.campus_id=?");$target->execute([$id,$actor['campus_id']]);$probation=$target->fetch();if(!$probation||$probation['onboardingStatus']!=='PROBATION'||$week>(int)$probation['weeks'])api_error('NOT_ON_PROBATION','This probation log is not available.',409);$super=$actor['access_level']==='TPK_SUPER_ADMIN';if(!$super&&!api_probation_staff_can_sign($db,$actor,$id,$date))api_error('NOT_ASSIGNED_TO_PROBATION_DAY','Only a teacher assigned with this volunteer that day, or a Super Admin, can sign this log.',403);$tribe=trim((string)($v['tribeAgeGroup']??''));$activity=trim((string)($v['lessonTopicActivity']??''));$time=trim((string)($v['timeIn']??''));if($time!==''&&!preg_match('/^\d{2}:\d{2}(:\d{2})?$/',$time))api_error('VALIDATION_ERROR','Enter a valid time in.',422);
    $db->prepare("INSERT INTO staff_probation_weekly_logs(staff_user_id,week_number,service_date,service_type,tribe_age_group,lesson_topic_activity,time_in,staff_signed_by_staff_user_id,staff_signed_at,super_admin_signed_by_staff_user_id,super_admin_signed_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE service_date=VALUES(service_date),service_type=VALUES(service_type),tribe_age_group=VALUES(tribe_age_group),lesson_topic_activity=VALUES(lesson_topic_activity),time_in=VALUES(time_in),staff_signed_by_staff_user_id=IF(VALUES(staff_signed_by_staff_user_id) IS NULL,staff_signed_by_staff_user_id,VALUES(staff_signed_by_staff_user_id)),staff_signed_at=IF(VALUES(staff_signed_at) IS NULL,staff_signed_at,VALUES(staff_signed_at)),super_admin_signed_by_staff_user_id=IF(VALUES(super_admin_signed_by_staff_user_id) IS NULL,super_admin_signed_by_staff_user_id,VALUES(super_admin_signed_by_staff_user_id)),super_admin_signed_at=IF(VALUES(super_admin_signed_at) IS NULL,super_admin_signed_at,VALUES(super_admin_signed_at))")->execute([$id,$week,$date,$serviceType,$tribe?:null,$activity?:null,$time?:null,$super?null:$actor['id'],$super?null:date('Y-m-d H:i:s'),$super?$actor['id']:null,$super?date('Y-m-d H:i:s'):null]);api_audit($db,$actor,$super?'PROBATION_LOG_SUPER_SIGNED':'PROBATION_LOG_STAFF_SIGNED','StaffUser',$id,['week'=>$week,'date'=>$date,'serviceType'=>$serviceType]);api_ok(['staffUserId'=>$id,'week'=>$week,'signedAs'=>$super?'SUPER_ADMIN':'ASSIGNED_STAFF']);
}
function api_probation_journey(PDO $db,int $id): never {
    $actor=api_actor($db);$profile=$db->prepare("SELECT s.id,s.name,s.joined_at AS joinedAt,COALESCE(op.onboarding_status,CASE WHEN s.team_status='PROBATION' THEN 'PROBATION' ELSE 'ONBOARDED' END) AS onboardingStatus,COALESCE(op.probation_started_at,DATE(s.joined_at)) AS probationStartedAt,COALESCE(op.probation_target_weeks,4) AS probationTargetWeeks FROM staff_users s LEFT JOIN staff_onboarding_profiles op ON op.staff_user_id=s.id WHERE s.id=? AND s.campus_id=?");$profile->execute([$id,$actor['campus_id']]);$teacher=$profile->fetch();if(!$teacher)api_error('STAFF_NOT_FOUND','This teacher is not available.',404);
    $orientation=$db->prepare("SELECT o.id,o.orientation_date AS orientationDate,o.attendance_status AS attendanceStatus,o.notes,o.confirmed_at AS confirmedAt,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,''),' ',COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))),''),s.name) AS confirmedBy FROM staff_orientation_records o JOIN staff_users s ON s.id=o.confirmed_by_staff_user_id LEFT JOIN teacher_profiles p ON p.staff_user_id=s.id WHERE o.staff_user_id=? ORDER BY o.orientation_date DESC,o.id DESC");$orientation->execute([$id]);$history=$orientation->fetchAll();$attended=null;foreach($history as $record)if($record['attendanceStatus']==='ATTENDED'){$attended=$record;break;}
    $logs=$db->prepare("SELECT l.week_number AS weekNumber,l.service_date AS serviceDate,l.service_type AS serviceType,l.tribe_age_group AS tribeAgeGroup,l.lesson_topic_activity AS lessonTopicActivity,l.time_in AS timeIn,l.teacher_reflection AS teacherReflection,l.leadership_review_note AS leadershipReviewNote,l.super_admin_signed_at AS confirmedAt,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(p.title,''),' ',COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))),''),u.name) AS confirmedBy FROM staff_probation_weekly_logs l LEFT JOIN staff_users u ON u.id=l.super_admin_signed_by_staff_user_id LEFT JOIN teacher_profiles p ON p.staff_user_id=u.id WHERE l.staff_user_id=? ORDER BY l.week_number");$logs->execute([$id]);$stored=[];foreach($logs->fetchAll() as $log)$stored[(int)$log['weekNumber']]=$log;
    $start=new DateTimeImmutable((string)$teacher['probationStartedAt']);$end=$start->modify('+'.(int)$teacher['probationTargetWeeks'].' weeks');$roster=$db->prepare("SELECT ra.assignment_date AS assignmentDate,ss.service_type AS serviceType,ss.name AS serviceName,c.name AS className,ra.status FROM roster_assignments ra LEFT JOIN service_sessions ss ON ss.id=ra.service_session_id LEFT JOIN classes c ON c.id=ra.class_id WHERE ra.user_id=? AND ra.assignment_date>=? AND ra.assignment_date<? AND ra.status NOT IN ('CANCELLED','REPLACED') ORDER BY ra.assignment_date,ra.id");$roster->execute([$id,$start->format('Y-m-d'),$end->format('Y-m-d')]);$rosterWeeks=[];foreach($roster->fetchAll() as $assignment){$number=max(1,min((int)$teacher['probationTargetWeeks'],(int)floor((strtotime($assignment['assignmentDate'])-$start->getTimestamp())/604800)+1));if(!isset($rosterWeeks[$number]))$rosterWeeks[$number]=$assignment;}
    $weeks=[];$completed=0;for($week=1;$week<=(int)$teacher['probationTargetWeeks'];$week++){ $assignment=$rosterWeeks[$week]??[];$row=$stored[$week]??[];$date=$row['serviceDate']??$assignment['assignmentDate']??$start->modify('+'.($week-1).' weeks')->format('Y-m-d');$confirmed=!empty($row['confirmedAt']);if($confirmed)$completed++;$weeks[]=['weekNumber'=>$week,'serviceDate'=>$date,'serviceType'=>$row['serviceType']??$assignment['serviceType']??null,'serviceName'=>$assignment['serviceName']??null,'tribeAgeGroup'=>$row['tribeAgeGroup']??$assignment['className']??null,'lessonTopicActivity'=>$row['lessonTopicActivity']??null,'timeIn'=>$row['timeIn']??null,'teacherReflection'=>$row['teacherReflection']??null,'leadershipReviewNote'=>$row['leadershipReviewNote']??null,'confirmedAt'=>$row['confirmedAt']??null,'confirmedBy'=>$row['confirmedBy']??null,'attendance'=>($assignment['status']??'')==='PRESENT'?'PRESENT':null]; }
    api_ok(['profile'=>$teacher,'orientation'=>['attended'=>$attended,'history'=>$history],'weeks'=>$weeks,'completedWeeks'=>$completed,'isSuperAdmin'=>$actor['access_level']==='TPK_SUPER_ADMIN','isSelf'=>(int)$actor['id']===$id]);
}
