dership_review_note=VALUES(leadership_review_note),super_admin_signed_by_staff_user_id=VALUES(super_admin_signed_by_staff_user_id),super_admin_signed_at=VALUES(super_admin_signed_at),attendance_confirmed_at=NOW()")->execute([$id,$week,$date,$service?:null,$tribe?:null,$activity?:null,$time?:null,$note?:null,$actor['id'],date('Y-m-d H:i:s')]);api_audit($db,$actor,'PROBATION_WEEK_CONFIRMED','StaffUser',$id,['week'=>$week,'continuedBeforeOrientation'=>!$hasOrientation]);api_ok(['staffUserId'=>$id,'week'=>$week]);
}
function api_finalize_onboarding(PDO $db,int $id): never {
    $actor=api_actor($db,true);$profile=$db->prepare("SELECT COALESCE(op.onboarding_status,CASE WHEN s.team_status='PROBATION' THEN 'PROBATION' ELSE 'ONBOARDED' END) AS onboardingStatus,COALESCE(op.probation_target_weeks,4) AS weeks FROM staff_users s LEFT JOIN staff_onboarding_profiles op ON op.staff_user_id=s.id WHERE s.id=? AND s.campus_id=?");$profile->execute([$id,$actor['campus_id']]);$teacher=$profile->fetch();if(!$teacher||$teacher['onboardingStatus']!=='PROBATION')api_error('NOT_ON_PROBATION','This teacher is not currently on probation.',409);$orientation=$db->prepare("SELECT COUNT(*) FROM staff_orientation_records WHERE staff_user_id=? AND attendance_status='ATTENDED'");$orientation->execute([$id]);$reviews=$db->prepare('SELECT COUNT(*) FROM staff_probation_weekly_logs WHERE staff_user_id=? AND super_admin_signed_at IS NOT NULL');$reviews->execute([$id]);if(!(int)$orientation->fetchColumn()||(int)$reviews->fetchColumn()<(int)$teacher['weeks'])api_error('ONBOARDING_INCOMPLETE','Complete orientation and every supported-service review before onboarding.',409);$db->prepare("UPDATE staff_onboarding_profiles SET onboarding_status='ONBOARDED',onboarded_at=NOW(),updated_by_staff_user_id=? WHERE staff_user_id=?")->execute([$actor['id'],$id]);$db->prepare("UPDATE staff_users SET team_status='ACTIVE' WHERE id=?")->execute([$id]);api_audit($db,$actor,'STAFF_ONBOARDING_FINALIZED','StaffUser',$id);api_ok(['staffUserId'=>$id,'onboardingStatus'=>'ONBOARDED']);
