/* Reports deliberately query only live operational tables.  Historical archive
   files are held in a separate table and never participate in these totals. */
function api_report_period(): array {
    $year=max(2020,min(2100,(int)($_GET['year']??date('Y'))));$month=max(1,min(12,(int)($_GET['month']??date('n'))));
    $start=sprintf('%04d-%02d-01',$year,$month);$end=(new DateTimeImmutable($start))->modify('+1 month')->format('Y-m-d');
    return [$year,$month,$start,$end];
}
function api_report_data(PDO $db,array $actor,int $year,int $month,string $start,string $end): array {
    $campus=(int)$actor['campus_id'];
    $attendance=$db->prepare("SELECT COUNT(*) AS childrenAttended,SUM(ss.service_type='FIRST_SERVICE') AS firstService,SUM(ss.service_type='SECOND_SERVICE') AS secondService,COUNT(DISTINCT CASE WHEN c.is_first_visit=1 THEN c.id END) AS firstTimeVisits FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id JOIN children c ON c.id=a.child_id WHERE ss.campus_id=? AND ss.service_date>=? AND ss.service_date<? AND a.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP')");$attendance->execute([$campus,$start,$end]);$summary=$attendance->fetch()?:[];
    $children=$db->prepare("SELECT COUNT(*) AS activeChildren,SUM(c.joined_at>=? AND c.joined_at<?) AS newRegistrations,SUM(c.date_of_birth IS NOT NULL AND c.gender IS NOT NULL AND c.class_id IS NOT NULL AND EXISTS(SELECT 1 FROM child_guardians cg JOIN guardians g ON g.id=cg.guardian_id WHERE cg.child_id=c.id AND cg.is_primary=1 AND g.phone IS NOT NULL AND g.phone<>'')) AS completeProfiles FROM children c JOIN families f ON f.id=c.family_id WHERE f.campus_id=? AND c.is_active=1");$children->execute([$start,$end,$campus]);$childTotals=$children->fetch()?:[];
    $follow=$db->prepare("SELECT COUNT(*) AS total,SUM(status='CONTACTED') AS contacted,SUM(status='COULDNT_REACH') AS couldntReach,SUM(status='RESOLVED') AS resolved,SUM(leadership_status IN ('SENT','LEADERSHIP_ATTENTION_REQUIRED')) AS escalated FROM follow_up_cases WHERE campus_id=? AND created_at>=? AND created_at<?");$follow->execute([$campus,$start,$end]);$followTotals=$follow->fetch()?:[];
    $pickup=$db->prepare("SELECT COUNT(*) AS checkedIn,SUM(a.status='PICKED_UP') AS completedPickups FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id WHERE ss.campus_id=? AND ss.service_date>=? AND ss.service_date<? AND a.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP')");$pickup->execute([$campus,$start,$end]);$pickupTotals=$pickup->fetch()?:[];
    $sunday=$db->prepare("SELECT ss.service_date AS serviceDate,SUM(ss.service_type='FIRST_SERVICE') AS firstService,SUM(ss.service_type='SECOND_SERVICE') AS secondService,COUNT(*) AS total FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id WHERE ss.campus_id=? AND ss.service_date>=? AND ss.service_date<? AND a.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP') GROUP BY ss.service_date ORDER BY ss.service_date");$sunday->execute([$campus,$start,$end]);$sundays=$sunday->fetchAll();
    $byClass=$db->prepare("SELECT COALESCE(cl.name,'Class pending') AS className,COUNT(*) AS attendance FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id LEFT JOIN classes cl ON cl.id=a.class_id WHERE ss.campus_id=? AND ss.service_date>=? AND ss.service_date<? AND a.status IN ('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP') GROUP BY cl.id,cl.name ORDER BY attendance DESC,className");$byClass->execute([$campus,$start,$end]);
