}
function api_reports_monthly(PDO $db): never {
    $actor=api_actor($db,true);[$year,$month,$start,$end]=api_report_period();$report=api_report_data($db,$actor,$year,$month,$start,$end);$months=[];
    for($m=1;$m<=12;$m++){ $from=sprintf('%04d-%02d-01',$year,$m);$to=(new DateTimeImmutable($from))->modify('+1 month')->format('Y-m-d');$exists=$db->prepare("SELECT COUNT(*) FROM attendance a JOIN service_sessions ss ON ss.id=a.service_session_id WHERE ss.campus_id=? AND ss.service_date>=? AND ss.service_date<?");$exists->execute([(int)$actor['campus_id'],$from,$to]);$count=(int)$exists->fetchColumn();$monthReport=$count?api_report_data($db,$actor,$year,$m,$from,$to):null;$months[]=['year'=>$year,'month'=>$m,'monthLabel'=>(new DateTimeImmutable($from))->format('F Y'),'sundays'=>$monthReport?count($monthReport['attendanceBySunday']):0,'available'=>$count>0,'attendance'=>$monthReport?$monthReport['summary']['childrenAttended']:0,'firstTimeVisits'=>$monthReport?$monthReport['summary']['firstTimeVisits']:0,'followUps'=>$monthReport?$monthReport['summary']['followUps']:0]; }
    api_ok(['selected'=>$report,'months'=>$months]);
}
function api_report_detail(PDO $db,int $year,int $month): never { $actor=api_actor($db,true);$start=sprintf('%04d-%02d-01',$year,$month);$end=(new DateTimeImmutable($start))->modify('+1 month')->format('Y-m-d');api_ok(api_report_data($db,$actor,$year,$month,$start,$end)); }
function api_archive_records(PDO $db): never {
    if(!api_table_exists($db,'historical_archive_records')){api_actor($db,true);[$page,$limit]=api_page();api_ok([],200,['page'=>$page,'limit'=>$limit,'total'=>0,'totalPages'=>1,'available'=>false]);}
    $actor=api_actor($db,true);[$page,$limit,$offset]=api_page();$where=['archive.campus_id=?','archive.is_archived=0'];$params=[(int)$actor['campus_id']];$search=trim((string)($_GET['search']??''));if($search!==''){$where[]='(archive.record_name LIKE ? OR archive.original_filename LIKE ? OR archive.description LIKE ?)';$params=array_merge($params,array_fill(0,3,'%'.$search.'%'));}if(($year=(int)($_GET['year']??0))>0){$where[]='YEAR(COALESCE(archive.period_start,archive.period_end))=?';$params[]=$year;}if(($type=trim((string)($_GET['type']??'')))!==''){ $where[]='archive.record_type=?';$params[]=$type;}$filter=' WHERE '.implode(' AND ',$where);$count=$db->prepare('SELECT COUNT(*) FROM historical_archive_records archive'.$filter);$count->execute($params);$total=(int)$count->fetchColumn();$sql="SELECT archive.id,archive.record_name AS recordName,archive.record_type AS recordType,archive.period_type AS periodType,archive.period_start AS periodStart,archive.period_end AS periodEnd,archive.description,archive.original_filename AS originalFilename,archive.mime_type AS mimeType,archive.file_size_bytes AS fileSizeBytes,archive.created_at AS uploadedAt,COALESCE(NULLIF(TRIM(CONCAT(COALESCE(profile.title,''),' ',COALESCE(profile.first_name,''),' ',COALESCE(profile.last_name,''))),''),staff.name) AS uploadedBy FROM historical_archive_records archive JOIN staff_users staff ON staff.id=archive.uploaded_by_staff_user_id LEFT JOIN teacher_profiles profile ON profile.staff_user_id=staff.id$filter ORDER BY archive.created_at DESC LIMIT $limit OFFSET $offset";$rows=$db->prepare($sql);$rows->execute($params);api_ok($rows->fetchAll(),200,['page'=>$page,'limit'=>$limit,'total'=>$total,'totalPages'=>max(1,(int)ceil($total/$limit))]);
}
function api_archive_download(PDO $db,int $id): never {
    $actor=api_actor($db,true);$record=$db->prepare('SELECT original_filename,stored_filename,mime_type FROM historical_archive_records WHERE id=? AND campus_id=? AND is_archived=0 LIMIT 1');$record->execute([$id,(int)$actor['campus_id']]);$file=$record->fetch();if(!$file)api_error('ARCHIVE_RECORD_NOT_FOUND','This historical record is not available.',404);$path=dirname(__DIR__).'/public/uploads/archive/'.basename((string)$file['stored_filename']);if(!is_file($path))api_error('ARCHIVE_FILE_NOT_FOUND','The original archive file is no longer available.',404);$downloadName=str_replace('"','',basename((string)$file['original_filename']));header('Access-Control-Allow-Origin: '.tpk_cors_origin());header('Vary: Origin');header('Access-Control-Expose-Headers: Content-Disposition');header('Content-Type: '.((string)$file['mime_type']?:'application/octet-stream'));header('Content-Length: '.(string)filesize($path));header('Content-Disposition: attachment; filename="'.$downloadName.'"');readfile($path);exit;
}
function api_archive_upload(PDO $db): never {
    $actor=api_actor($db,true);$file=$_FILES['file']??null;if(!is_array($file)||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)api_error('VALIDATION_ERROR','Choose a historical file to upload.',422);if(($file['size']??0)>20*1024*1024)api_error('VALIDATION_ERROR','Archive files must be 20 MB or smaller.',422);$name=trim((string)($_POST['recordName']??''));$type=strtoupper(trim((string)($_POST['recordType']??'')));$periodType=strtoupper(trim((string)($_POST['periodType']??'')));$allowedTypes=['ATTENDANCE','CHILDREN_RECORDS','REGISTRATION_RECORDS','FOLLOW_UP_RECORDS','TEAM_ROSTER','OTHER'];$allowedPeriods=['SINGLE_MONTH','DATE_RANGE','FULL_YEAR'];if($name===''||!in_array($type,$allowedTypes,true)||!in_array($periodType,$allowedPeriods,true))api_error('VALIDATION_ERROR','Complete the record name, type, and period.',422);$start=trim((string)($_POST['periodStart']??''));$end=trim((string)($_POST['periodEnd']??''));if(($start!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start))||($end!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end)))api_error('VALIDATION_ERROR','Choose a valid period.',422);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$extensions=['application/pdf'=>'pdf','text/csv'=>'csv','application/vnd.ms-excel'=>'xls','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'=>'xlsx','application/msword'=>'doc','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx'];if(!isset($extensions[$mime]))api_error('VALIDATION_ERROR','Use an XLS, XLSX, CSV, PDF, DOC, or DOCX file.',422);$dir=dirname(__DIR__).'/public/uploads/archive';if(!is_dir($dir)&&!mkdir($dir,0750,true)&&!is_dir($dir))api_error('STORAGE_UNAVAILABLE','Archive storage is unavailable.',503);$stored='archive-'.bin2hex(random_bytes(16)).'.'.$extensions[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$stored))api_error('STORAGE_UNAVAILABLE','The historical file could not be stored.',503);$insert=$db->prepare('INSERT INTO historical_archive_records(campus_id,record_name,record_type,period_type,period_start,period_end,description,original_filename,stored_filename,mime_type,file_size_bytes,uploaded_by_staff_user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$insert->execute([(int)$actor['campus_id'],$name,$type,$periodType,$start?:null,$end?:null,trim((string)($_POST['description']??''))?:null,basename((string)$file['name']),$stored,$mime,(int)$file['size'],(int)$actor['id']]);$id=(int)$db->lastInsertId();api_audit($db,$actor,'HISTORICAL_ARCHIVE_UPLOADED','HistoricalArchiveRecord',$id,['recordType'=>$type,'archiveOnly'=>true]);api_ok(['id'=>$id,'archiveOnly'=>true],201);
}

